const state = {
  token:'', currentView:'institutions', currentInstitution:null, customFields:[], financeFields:[],
  institutions:[], institutionGroups:[], allInstitutions:[], groups:[], tableColumns:[], financeTableColumns:[], columnDraft:[], columnMode:'institutions',
  filterData:{}, activeFilters:[], institutionSelections:{}, financeSelections:{}, financeRanges:{},
  institutionFilterConfig:[], financeFilterConfig:[], filterMode:'institutions', filterDraft:[], financeSavedViews:[],
  expandedGroups:new Set(), expandedFinanceGroups:new Set(), importToken:'', institutionRequest:0,
  financeData:null, commissionRules:[], editingCommissionRule:null, selectedInstitutions:new Set(), archivedFinanceFields:[], archivedInstitutions:[], archivedCustomFields:[],
  lookupCategories:[], institutionFormFields:[], institutionFormDraft:[], financeSummaryCards:[], financeCardDraft:[],
  navigationPreferences:[], navigationDraft:[], themePreferences:{}, activeFinanceView:null, editingLookupItem:null, editingFinanceCard:null,
  institutionPhotoData:null, institutionPhotoRemove:false,
  platformBootstrap:{modules:[],core_modules:[],relations:{institutions:[]}}, dynamicModules:[], currentDynamicModule:null,
  dynamicData:null, dynamicSelections:{}, dynamicRanges:{}, dynamicViews:[], dynamicSelectedRecords:new Set(), studioModule:null, platformPreviewToken:'', platformPreviewMode:'platform', platformAfterCommit:null,
  assistantImageData:'', assistantStatus:{configured:false,mode:'local-fallback',model:'gpt-5.6'},
};
const $=(selector,root=document)=>root.querySelector(selector);
const $$=(selector,root=document)=>[...root.querySelectorAll(selector)];
const esc=value=>String(value??'').replace(/[&<>'"]/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[ch]));
const display=(value,fallback='—')=>value===null||value===undefined||value===''?fallback:esc(value);
const number=value=>Number(value||0).toLocaleString('tr-TR');
const money=minor=>new Intl.NumberFormat('tr-TR',{style:'currency',currency:'TRY'}).format(Number(minor||0)/100);
const decimal=value=>{let text=String(value??'0').trim();if(text.includes(','))text=text.replace(/\./g,'').replace(',','.');const parsed=Number(text);return Number.isFinite(parsed)?parsed:0;};
function refreshTopScrollbars(){for(const top of $$('.table-scroll-top')){const target=$(top.dataset.scrollSync);if(!target)continue;const spacer=$('div',top);spacer.style.width=`${Math.max(target.scrollWidth,target.clientWidth)}px`;top.hidden=target.scrollWidth<=target.clientWidth+1;if(!top.dataset.syncBound){top.dataset.syncBound='1';let syncing=false;top.addEventListener('scroll',()=>{if(syncing)return;syncing=true;target.scrollLeft=top.scrollLeft;syncing=false;});target.addEventListener('scroll',()=>{if(syncing)return;syncing=true;top.scrollLeft=target.scrollLeft;syncing=false;});}if(Math.abs(top.scrollLeft-target.scrollLeft)>1)top.scrollLeft=target.scrollLeft;}}
const DEFAULT_THEME={background:'#f4f7f6',surface:'#ffffff',text:'#15231e',muted:'#687871',primary:'#15865d',primary_dark:'#0d6847',danger:'#c34242',sidebar:'#0d2a21',font_scale:100,density:'normal',radius:12,sidebar_width:220};
const DEFAULT_FINANCE_CARDS=[{id:'card_institution',label:'Kurum',metric:'institution_count',format:'number',subtitle:'Çatı kurum sayısı',color:'neutral',visible:true},{id:'card_revenue',label:'Toplam Ciro',metric:'field:toplam_ciro',format:'money',subtitle:'Filtrelenmiş sonuç',color:'neutral',visible:true},{id:'card_paid',label:'Tahsil Edilen',metric:'field:tahsilat',format:'money',subtitle:'Filtrelenmiş sonuç',color:'success',visible:true},{id:'card_balance',label:'Bakiye',metric:'field:bakiye',format:'money',subtitle:'Filtrelenmiş sonuç',color:'danger',visible:true}];

function toast(message,error=false){const node=$('#toast');node.textContent=message;node.className=`toast show${error?' error':''}`;clearTimeout(toast.timer);toast.timer=setTimeout(()=>node.className='toast',3400);}
async function api(path,options={}){const settings={...options,headers:{...(options.headers||{})}};if(settings.method&&settings.method!=='GET')settings.headers['X-App-Token']=state.token;if(settings.body&&!(settings.body instanceof ArrayBuffer)&&typeof settings.body!=='string'){settings.headers['Content-Type']='application/json';settings.body=JSON.stringify(settings.body);}const response=await fetch(path,settings);const type=response.headers.get('content-type')||'';const result=type.includes('application/json')?await response.json():await response.text();if(!response.ok||(result&&result.ok===false))throw new Error(result.error||`İşlem başarısız (${response.status})`);return result;}

function lookupCategory(key){return state.lookupCategories.find(item=>item.category_key===key);}
function lookupItems(key,{active=true,parent=null,current=''}={}){const category=lookupCategory(key);if(!category)return[];return(category.items||[]).filter(item=>(!active||item.active||item.item_key===current)&&(parent===null||item.parent_item_key===parent));}
function lookupLabel(key,value){if(value===null||value===undefined||value==='')return'';const item=lookupItems(key,{active:false}).find(entry=>entry.item_key===String(value));return item?.label||String(value);}
function lookupOptionObjects(key,parent=null){return lookupItems(key,{parent}).map(item=>({value:item.item_key,label:item.label,count:item.filter_count??item.usage_count,color:item.color}));}
function formField(key){return state.institutionFormFields.find(item=>item.key===key);}
function fieldLabel(key,fallback=''){return formField(key)?.label||fallback||key;}
async function loadLookups(){state.lookupCategories=(await api('/api/lookups')).data;state.filterData.lookups=Object.fromEntries(state.lookupCategories.map(category=>[category.category_key,(category.items||[]).filter(item=>item.active)]));}

function baseColumns(){return[
  {key:'select',label:'',width:46,visible:true,locked:true,pinned:true},
  {key:'list_number',label:'No',width:64,visible:true,pinned:true},
  {key:'group_number',label:'Grup',width:108,visible:true,pinned:true},
  {key:'sequence_number',label:'Kayıt sıra',width:82,visible:true},
  {key:'institution',label:'Kurum',width:355,visible:true,locked:true,pinned:true},
  {key:'photo',label:'Foto',width:70,visible:true,pinned:true},
  {key:'identity',label:'Kimlik',width:145,visible:true},
  {key:'location',label:'Konum',width:150,visible:false},
  {key:'status',label:'Durum',width:190,visible:true},
  {key:'panel',label:'Panel',width:105,visible:true},
  {key:'turnstile',label:'Turnike',width:90,visible:true},
  {key:'last_seen',label:'Son bağlantı',width:150,visible:true},
  {key:'installation_date',label:'Kurulum',width:130,visible:false},
  {key:'sales_person',label:'Satışı yapan',width:150,visible:false},
  {key:'technical_person',label:'Teknik servis',width:150,visible:false},
  {key:'accounting_person',label:'Muhasebe',width:150,visible:false},
  {key:'actions',label:'',width:205,visible:true,locked:true},
];}
function availableColumns(){const columns=baseColumns();for(const field of state.customFields.filter(item=>item.entity_type==='institution'))columns.splice(columns.length-1,0,{key:`custom:${field.id}`,label:field.label,width:150,visible:false});return columns;}
function mergeColumnSet(available,saved=[]){const byKey=new Map(available.map(item=>[item.key,item])),result=[];if(Array.isArray(saved))for(const setting of saved){const base=byKey.get(setting.key);if(!base)continue;const minimum=base.key==='actions'?base.width:44;result.push({...base,label:String(setting.label||base.label),visible:base.locked?true:setting.visible!==false,pinned:setting.pinned===undefined?Boolean(base.pinned):Boolean(setting.pinned),width:Math.min(600,Math.max(minimum,Number(setting.width)||base.width))});byKey.delete(setting.key);}for(const item of available)if(byKey.has(item.key))result.push(item);return result;}
function mergeColumns(saved=[]){const merged=mergeColumnSet(availableColumns(),saved);for(const key of['list_number','select']){const index=merged.findIndex(item=>item.key===key);if(index>0)merged.unshift(merged.splice(index,1)[0]);}const institutionIndex=merged.findIndex(item=>item.key==='institution'),photoIndex=merged.findIndex(item=>item.key==='photo');if(institutionIndex>=0&&photoIndex>=0&&photoIndex!==institutionIndex+1){const[photo]=merged.splice(photoIndex,1),target=merged.findIndex(item=>item.key==='institution');merged.splice(target+1,0,photo);}return merged;}
function availableFinanceColumns(){return[
  {key:'list_number',label:'No',width:64,visible:true,pinned:true},
  {key:'group_number',label:'Grup',width:108,visible:true,pinned:true},
  {key:'sequence_number',label:'Kayıt sıra',width:82,visible:false},
  {key:'institution',label:'Kurum',width:330,visible:true,locked:true,pinned:true},
  {key:'city',label:'Şehir / İlçe',width:150,visible:true},
  {key:'sales_person',label:'Satış Temsilcisi',width:145,visible:true},
  ...state.financeFields.map(field=>({key:`finance:${field.field_key}`,label:field.label,width:145,visible:Boolean(field.visible)})),
  {key:'actions',label:'',width:92,visible:true,locked:true},
];}
function mergeFinanceColumns(saved=[]){return mergeColumnSet(availableFinanceColumns(),saved);}
function stickyColumns(columns){let left=0;return columns.map(column=>{const value={...column,stickyLeft:column.pinned?left:null};if(column.pinned)left+=column.width;return value;});}
function cellAttrs(column,extra=''){return `${extra?` class="${extra}${column.pinned?' sticky-column':''}"`:(column.pinned?' class="sticky-column"':'')} ${column.pinned?`style="--sticky-left:${column.stickyLeft}px"`:''}`;}

const filterCatalog=(selections=state.institutionSelections)=>[
  {key:'city',label:fieldLabel('city','İller'),placeholder:'Tüm iller',values:lookupOptionObjects('city')},
  {key:'district',label:'İlçeler',placeholder:'Tüm ilçeler',values:districtValues(selections)},
  {key:'health',label:fieldLabel('health_status','Çalışma durumları'),placeholder:'Tüm çalışma durumları',values:lookupOptionObjects('health_status')},
  {key:'status',label:fieldLabel('customer_status','Satış durumları'),placeholder:'Tüm satış durumları',values:lookupOptionObjects('customer_status')},
  {key:'sales_person',label:fieldLabel('sales_person','Satış temsilcileri'),placeholder:'Tüm satış temsilcileri',values:lookupOptionObjects('sales_person')},
  {key:'technical_person',label:fieldLabel('technical_person','Teknik servis'),placeholder:'Tüm teknik servisler',values:lookupOptionObjects('technical_person')},
  {key:'school_type',label:fieldLabel('school_type','Okul türleri'),placeholder:'Tüm okul türleri',values:lookupOptionObjects('school_type')},
  {key:'sales_period',label:fieldLabel('sales_period','Satış dönemleri'),placeholder:'Tüm satış dönemleri',values:lookupOptionObjects('sales_period')},
  {key:'dealer',label:fieldLabel('dealer','Bayiler'),placeholder:'Tüm bayiler',values:lookupOptionObjects('dealer')},
  {key:'marketing_person',label:fieldLabel('marketing_person','Pazarlama temsilcileri'),placeholder:'Tüm pazarlama temsilcileri',values:lookupOptionObjects('marketing_person')},
  {key:'accounting_person',label:fieldLabel('accounting_person','Muhasebe temsilcileri'),placeholder:'Tüm muhasebe temsilcileri',values:lookupOptionObjects('accounting_person')},
  {key:'customer_person',label:fieldLabel('customer_person','Müşteri temsilcileri'),placeholder:'Tüm müşteri temsilcileri',values:lookupOptionObjects('customer_person')},
  {key:'payment_status',label:fieldLabel('payment_status','Ödeme durumları'),placeholder:'Tüm ödeme durumları',values:lookupOptionObjects('payment_status')},
  ...(state.filterData.custom_fields||[]).map(field=>({key:`custom.${field.id}`,label:field.label,placeholder:`Tüm ${field.label}`,values:field.values||[]})),
];
function financeFilterCatalog(){const base=filterCatalog(state.financeSelections).filter(item=>['city','district','status','sales_person'].includes(item.key));const financeRows=state.financeData?.items||[];const dynamic=state.financeFields.filter(field=>field.filterable).map(field=>{let values=field.options||[];if(!values.length&&!['number','money','formula','date'].includes(field.data_type))values=[...new Set(financeRows.map(row=>(row.finance_values||{})[field.field_key]).filter(Boolean))].sort((a,b)=>String(a).localeCompare(String(b),'tr'));return{key:`finance.${field.field_key}`,label:field.label,placeholder:`Tüm ${field.label}`,values,data_type:field.data_type};});return[...base,...dynamic];}
function normalizeFilterConfig(catalog,saved=[],defaultKeys=null){const byKey=new Map(catalog.map(item=>[item.key,item])),result=[];const raw=Array.isArray(saved)?saved:[];for(const entry of raw){const setting=typeof entry==='string'?{key:entry,visible:true}:entry,base=byKey.get(setting.key);if(!base)continue;result.push({...base,label:String(setting.label||base.label),visible:setting.visible!==false,width:Math.min(500,Math.max(140,Number(setting.width)||180)),pinned:Boolean(setting.pinned)});byKey.delete(setting.key);}for(const item of catalog)if(byKey.has(item.key)){const visible=defaultKeys?defaultKeys.includes(item.key):true;result.push({...item,visible,width:180,pinned:false});}return result;}
function districtValues(selections){const selected=selections.city||[];if(!selected.length)return lookupOptionObjects('district').filter((item,index,array)=>array.findIndex(other=>other.value===item.value)===index);return selected.flatMap(city=>lookupOptionObjects('district',city));}
function normalizedOptions(values=[]){return values.map(value=>typeof value==='object'?{value:String(value.value??value.item_key??''),label:String(value.label??value.value??''),count:value.count??value.usage_count,color:value.color||''}:{value:String(value),label:String(value),count:null,color:''});}
function optionLabel(item,value){return normalizedOptions(item.values).find(option=>option.value===String(value))?.label||String(value);}
function filterSummary(item,selected){if(!selected.length)return item.placeholder;if(selected.length===1)return optionLabel(item,selected[0]);return `${item.label} (${selected.length})`;}
function multiFilterHtml(item,selections,scope){const selected=new Set(selections[item.key]||[]),options=normalizedOptions(item.values),chips=[...selected].map(value=>`<button type="button" data-remove-filter-value="${esc(value)}">${esc(optionLabel(item,value))} ×</button>`).join('');return `<details class="multi-filter" data-filter-key="${esc(item.key)}" data-filter-label="${esc(item.label)}" data-filter-placeholder="${esc(item.placeholder)}" data-scope="${scope}"><summary><span>${esc(filterSummary(item,[...selected]))}</span><b>⌄</b></summary><div class="multi-menu"><input class="filter-option-search" type="search" placeholder="Listede ara…">${chips?`<div class="selected-filter-chips">${chips}</div>`:''}<div class="multi-actions"><button type="button" data-select-all>Tümünü seç</button><button type="button" data-clear-selection>Temizle</button></div><div class="multi-options">${options.map(option=>`<label><input type="checkbox" value="${esc(option.value)}" ${selected.has(option.value)?'checked':''}>${option.color?`<i class="lookup-color" style="background:${esc(option.color)}"></i>`:''}<span>${esc(option.label)}${option.count!==null?` <small>(${number(option.count)})</small>`:''}</span></label>`).join('')||'<span class="subtext">Seçenek yok</span>'}</div><button class="button primary compact filter-apply" type="button" data-apply-filter>Uygula ve Kapat</button></div></details>`;}
function renderInstitutionFilters(){state.institutionFilterConfig=normalizeFilterConfig(filterCatalog(),state.institutionFilterConfig,['city','district','health','status','sales_person']);state.activeFilters=state.institutionFilterConfig.filter(item=>item.visible).map(item=>item.key);$('#institutionFilters').innerHTML=state.institutionFilterConfig.filter(item=>item.visible).map(item=>{const html=multiFilterHtml(item,state.institutionSelections,'institution');return html.replace('class="multi-filter"',`class="multi-filter" style="flex-basis:${item.width}px;max-width:${Math.max(item.width,220)}px"`);}).join('');}
function renderFinanceFilters(){state.financeFilterConfig=normalizeFilterConfig(financeFilterCatalog(),state.financeFilterConfig);$('#financeFilters').innerHTML=state.financeFilterConfig.filter(item=>item.visible).map(item=>{const html=item.data_type&&['number','money','formula','date'].includes(item.data_type)?rangeFilterHtml(item):multiFilterHtml(item,state.financeSelections,'finance');return html.replace('class="multi-filter',`style="flex-basis:${item.width}px;max-width:${Math.max(item.width,220)}px" class="multi-filter`);}).join('');}
function rangeFilterHtml(item){const range=state.financeRanges[item.key]||{};const date=item.data_type==='date';return `<details class="multi-filter range-filter" data-filter-key="${esc(item.key)}" data-scope="finance" data-range-type="${esc(item.data_type)}"><summary><span>${esc(range.min||range.max?`${range.min||'…'} – ${range.max||'…'}`:item.placeholder)}</span><b>⌄</b></summary><div class="multi-menu range-menu"><label>Başlangıç<input data-range-min type="${date?'date':'number'}" step="any" value="${esc(range.min||'')}"></label><label>Bitiş<input data-range-max type="${date?'date':'number'}" step="any" value="${esc(range.max||'')}"></label><button class="button secondary compact" type="button" data-apply-range>Uygula</button></div></details>`;}
function bindFilterContainer(container){container.addEventListener('input',event=>{if(event.target.classList.contains('filter-option-search')){const term=event.target.value.toLocaleLowerCase('tr-TR');$$('.multi-options label',event.target.closest('.multi-menu')).forEach(label=>label.hidden=!label.textContent.toLocaleLowerCase('tr-TR').includes(term));}});container.addEventListener('change',event=>{if(event.target.type!=='checkbox')return;const box=event.target.closest('.multi-filter'),scope=box.dataset.scope,key=box.dataset.filterKey,target=scope==='finance'?state.financeSelections:state.institutionSelections,catalog=(scope==='finance'?financeFilterCatalog():filterCatalog()).find(item=>item.key===key);target[key]=$$('input[type="checkbox"]:checked',box).map(input=>input.value);$('summary span',box).textContent=target[key].length===0?box.dataset.filterPlaceholder:target[key].length===1?optionLabel(catalog||{values:[]},target[key][0]):`${box.dataset.filterLabel} (${target[key].length})`;scope==='finance'?loadFinance(false):refreshInstitutions();});container.addEventListener('click',event=>{const box=event.target.closest('.multi-filter');if(!box)return;const scope=box.dataset.scope,key=box.dataset.filterKey,target=scope==='finance'?state.financeSelections:state.institutionSelections,refresh=()=>scope==='finance'?loadFinance(false):refreshInstitutions(),rerender=()=>scope==='finance'?renderFinanceFilters():renderInstitutionFilters();const remove=event.target.closest('[data-remove-filter-value]');if(remove){target[key]=(target[key]||[]).filter(value=>value!==remove.dataset.removeFilterValue);refresh();rerender();return;}if(event.target.closest('[data-select-all]')){target[key]=$$('input[type="checkbox"]',box).map(input=>input.value);refresh();rerender();return;}if(event.target.closest('[data-clear-selection]')){target[key]=[];refresh();rerender();return;}if(event.target.closest('[data-apply-filter]')){box.open=false;rerender();return;}if(event.target.closest('[data-apply-range]')){state.financeRanges[key]={min:$('[data-range-min]',box).value,max:$('[data-range-max]',box).value};box.open=false;loadFinance();renderFinanceFilters();}});}
function appendSelections(params,selections){for(const[key,values]of Object.entries(selections))for(const value of values||[])if(value)params.append(key,value);}
function institutionParams(){const params=new URLSearchParams(),query=$('#searchInput').value.trim();if(query)params.append('query',query);appendSelections(params,state.institutionSelections);return params;}
function financeParams(){const params=new URLSearchParams(),query=$('#financeSearch').value.trim();if(query)params.append('finance_query',query);appendSelections(params,state.financeSelections);for(const[key,range]of Object.entries(state.financeRanges)){const fieldKey=key.replace(/^finance\./,''),definition=state.financeFields.find(field=>field.field_key===fieldKey),date=definition?.data_type==='date';if(range.min)params.append(`${date?'from':'min'}.${fieldKey}`,range.min);if(range.max)params.append(`${date?'to':'max'}.${fieldKey}`,range.max);}return params;}

function healthBadge(value){if(!value)return'<span class="badge">Belirsiz</span>';const label=lookupLabel('health_status',value),upper=label.toLocaleUpperCase('tr-TR'),cls=upper.includes('HATA')?'danger':'success';return`<span class="badge ${cls}">${esc(label)}</span>`;}
function statusBadge(item){const value=item.customer_status||'';if(!value)return'<span class="badge">Belirsiz</span>';const label=lookupLabel('customer_status',value),upper=label.toLocaleUpperCase('tr-TR'),cls=upper==='AKTİF'?'success':upper.includes('İPTAL')||upper.includes('BIRAK')||upper.includes('RAKİP')?'danger':'warning';return`<span class="badge ${cls}">${esc(label)}</span>`;}
function institutionDisplayValue(key,value){const field=formField(key);return field?.lookup_category?lookupLabel(field.lookup_category,value):String(value??'');}
function institutionCell(column,item,group=null,child=false,listNo=''){
  if(group&&!item){const allSelected=group.children.every(row=>state.selectedInstitutions.has(row.id));switch(column.key){case'select':return`<input type="checkbox" data-select-group="${esc(group.id)}" ${allSelected?'checked':''} aria-label="Grubun tüm kurumlarını seç">`;case'list_number':return`<span class="number-badge sequence">${esc(listNo)}</span>`;case'group_number':return`<div class="tree-group-cell"><button class="tree-toggle" type="button" data-toggle-group="${esc(group.id)}">${state.expandedGroups.has(group.id)?'−':'+'}</button><span class="number-badge group">${display(group.group_number)}</span></div>`;case'institution':return`<div class="institution-cell group-title"><strong>${esc(group.name)}</strong><span>${number(group.children.length)} alt kurum · ${number(group.panel_count)} panel</span></div>`;case'photo':return'<span class="subtext">—</span>';case'location':return`${display(lookupLabel('city',group.city))}<span class="subtext">${display(lookupLabel('district',group.district),'')}</span>`;case'status':return group.error_panel_count?'<span class="badge danger">Hata var</span>':'<span class="badge success">Sorun yok</span>';case'panel':return`<span class="badge blue">${number(group.panel_count)} panel</span>`;case'turnstile':return`<strong>${number(group.turnstile_count)}</strong>`;case'actions':return`<div class="row-action-set"><button data-edit-group="${esc(group.id)}">Düzenle</button><button class="danger-action" data-delete-group="${esc(group.id)}">Sil</button></div>`;default:return'';}}
  const location=[lookupLabel('city',item.city),lookupLabel('district',item.district),lookupLabel('school_type',item.school_type)].filter(Boolean).join(' · ');
  switch(column.key){case'select':return`<input type="checkbox" data-select-institution="${esc(item.id)}" ${state.selectedInstitutions.has(item.id)?'checked':''} aria-label="Kurumu seç">`;case'list_number':return`<span class="number-badge sequence">${esc(listNo)}</span>`;case'group_number':return`<span class="number-badge group">${display(item.group_number)}</span>`;case'sequence_number':return`<span class="number-badge sequence">${display(item.sequence_number)}</span>`;case'institution':return`<div class="institution-cell ${child?'child-cell':''}"><strong>${esc(item.name)}</strong><span>${esc(location)}</span></div>`;case'photo':return item.has_photo?`<img class="institution-photo-thumb" src="/api/institutions/${encodeURIComponent(item.id)}/photo?v=${encodeURIComponent(item.updated_at||'')}" alt="${esc(item.name)} fotoğrafı">`:'<span class="institution-photo-placeholder">Yok</span>';case'identity':return`<div class="id-stack"><code>ID: ${display(item.portal_id)}</code><code>Kod: ${display(item.institution_code)}</code></div>`;case'location':return`${display(lookupLabel('city',item.city))}<span class="subtext">${display(lookupLabel('district',item.district),'')}</span>`;case'status':return`${healthBadge(item.health_status)}<span class="subtext">${statusBadge(item)}</span>`;case'panel':return`<span class="badge blue">${number(item.panel_count)} panel</span>`;case'turnstile':return`<strong>${number(item.turnstile_count)}</strong><span class="subtext">kayıtlı adet</span>`;case'last_seen':return`${display(item.last_seen)}<span class="subtext">${display(lookupLabel('technical_person',item.technical_person),'')}</span>`;case'installation_date':return`${display(item.installation_date)}<span class="subtext">${display(item.installed_by,'')}</span>`;case'sales_person':return display(lookupLabel('sales_person',item.sales_person));case'technical_person':return display(lookupLabel('technical_person',item.technical_person));case'accounting_person':return display(lookupLabel('accounting_person',item.accounting_person));case'actions':return`<div class="row-action-set"><button data-detail-id="${esc(item.id)}">Aç</button><button data-edit-group="${esc(item.group_id)}">Grup</button><button class="danger-action" data-delete-institution="${esc(item.id)}">Sil</button></div>`;default:return column.key.startsWith('custom:')?display((item.custom_values||{})[column.key.slice(7)]):'—';}
}
function updateInstitutionSelectionUi(){const count=state.selectedInstitutions.size,button=$('#deleteSelectedInstitutions');button.disabled=!count;button.textContent=count?`${number(count)} Kurumu Sil`:'Seçilenleri Sil';const visibleIds=state.institutions.map(item=>item.id);$('#selectVisibleInstitutions').checked=Boolean(visibleIds.length)&&visibleIds.every(id=>state.selectedInstitutions.has(id));}
function renderInstitutionTable(){const visible=stickyColumns(state.tableColumns.filter(item=>item.visible));$('#institutionsColgroup').innerHTML=visible.map(item=>`<col style="width:${item.width}px">`).join('');$('#institutionsHead').innerHTML=visible.map(item=>`<th${cellAttrs(item,item.key==='select'?'row-select':'')}>${esc(item.label)}</th>`).join('');$('#institutionsTable').style.minWidth=`${visible.reduce((sum,item)=>sum+item.width,0)}px`;const rows=[];state.institutionGroups.forEach((group,groupIndex)=>{const parentNo=groupIndex+1;if(group.children.length===1){const item=group.children[0];rows.push(`<tr data-institution-row="${esc(item.id)}">${visible.map(column=>`<td${cellAttrs(column,column.key==='actions'?'row-actions':column.key==='select'?'row-select':'')}>${institutionCell(column,item,null,false,parentNo)}</td>`).join('')}</tr>`);}else{rows.push(`<tr class="group-row">${visible.map(column=>`<td${cellAttrs(column,column.key==='actions'?'row-actions':column.key==='select'?'row-select':'')}>${institutionCell(column,null,group,false,parentNo)}</td>`).join('')}</tr>`);if(state.expandedGroups.has(group.id))group.children.forEach((item,childIndex)=>rows.push(`<tr class="child-row" data-institution-row="${esc(item.id)}">${visible.map(column=>`<td${cellAttrs(column,column.key==='actions'?'row-actions':column.key==='select'?'row-select':'')}>${institutionCell(column,item,null,true,`${parentNo}.${childIndex+1}`)}</td>`).join('')}</tr>`));}});$('#institutionsBody').innerHTML=rows.join('');updateInstitutionSelectionUi();requestAnimationFrame(refreshTopScrollbars);}
async function refreshInstitutions(){const request=++state.institutionRequest,params=institutionParams(),suffix=params.toString()?`?${params}`:'';try{const[dashboardResult,listResult]=await Promise.all([api(`/api/dashboard${suffix}`),api(`/api/institutions${suffix}`)]);if(request!==state.institutionRequest)return;const dashboard=dashboardResult.data,data=listResult.data;$('#kpiInstitutions').textContent=number(dashboard.institution_count);$('#kpiPanels').textContent=number(dashboard.panel_count);$('#kpiErrorInstitutions').textContent=number(dashboard.error_institution_count);$('#kpiErrors').textContent=number(dashboard.error_panel_count);$('#kpiContext').textContent=params.toString()?'Filtrelenmiş sonuç':'Tüm çatı kurumlar';state.institutions=data.items;state.institutionGroups=data.groups;$('#resultCount').textContent=`${number(data.total)} kurum`;$('#resultSummary').textContent=`${number(data.record_total)} alt kurum/panel kaydı · liste 1’den yeniden numaralandırıldı`;$('#emptyState').hidden=data.groups.length!==0;renderInstitutionTable();}catch(error){toast(error.message,true);}}
async function loadFilters(){state.filterData=(await api('/api/filters')).data;renderInstitutionFilters();renderFinanceFilters();}
async function loadAllInstitutions(){const data=(await api('/api/institutions')).data;state.allInstitutions=data.items;state.groups=await api('/api/groups').then(result=>result.data);}

function detailItem(label,value){return`<div class="detail-item"><span>${esc(label)}</span><strong>${display(value)}</strong></div>`;}
function panelCard(panel){return`<article class="panel-card"><header><div><h4>${display(panel.name,'Panel')}</h4><span class="subtext">${display(panel.panel_key)}</span></div><button class="button ghost compact" data-edit-panel="${esc(panel.id)}">Düzenle</button></header><div class="panel-meta"><div>Turnike<strong>${display(panel.turnstile_count)}</strong></div><div>Yerel IP<strong>${display(panel.local_ip)}</strong></div><div>Son bağlantı<strong>${display(panel.last_seen)}</strong></div><div>Kurulum<strong>${display(panel.installation_date)}</strong></div><div>Durum<strong>${display(panel.status)}</strong></div></div></article>`;}
async function openDetail(id){try{const item=(await api(`/api/institutions/${encodeURIComponent(id)}`)).data;state.currentInstitution=item;$('#detailName').textContent=item.name;const configured=state.institutionFormFields.filter(field=>field.visible&&!['notes','pilot','name'].includes(field.key)).map(field=>detailItem(field.label,institutionDisplayValue(field.key,item[field.key]))).join(''),custom=state.customFields.filter(field=>field.entity_type==='institution').map(field=>detailItem(field.label,item.custom_values[field.id])).join(''),photo=item.photo?`<div class="institution-detail-photo"><img src="/api/institutions/${encodeURIComponent(item.id)}/photo?v=${encodeURIComponent(item.photo.updated_at||'')}" alt="${esc(item.name)} fotoğrafı"><span>Kurum fotoğrafı · ${esc(item.photo.original_name||'fotoğraf')}</span></div>`:'';$('#detailContent').innerHTML=`${photo}<div class="detail-grid">${configured}${custom}</div>${item.notes?`<div class="notice">${esc(item.notes)}</div>`:''}<div class="section-title"><h3>Panel ve turnikeler</h3><span>${number(item.panels.length)} panel</span></div>${item.panels.length?item.panels.map(panelCard).join(''):'<div class="notice">Bu kurum için panel kaydı yok.</div>'}`;$('#detailDrawer').classList.add('open');$('#detailDrawer').setAttribute('aria-hidden','false');}catch(error){toast(error.message,true);}}
function closeDrawer(){$('#detailDrawer').classList.remove('open');$('#detailDrawer').setAttribute('aria-hidden','true');}
function customInput(field,value=''){const name=`custom_${field.id}`;if(field.data_type==='list')return`<label>${esc(field.label)}<select name="${name}"><option value=""></option>${field.options.map(option=>`<option ${String(value)===String(option)?'selected':''}>${esc(option)}</option>`).join('')}</select></label>`;if(field.data_type==='boolean')return`<label>${esc(field.label)}<select name="${name}"><option value=""></option><option ${value==='Evet'?'selected':''}>Evet</option><option ${value==='Hayır'?'selected':''}>Hayır</option></select></label>`;const type=field.data_type==='date'?'date':field.data_type==='number'?'number':'text';return`<label>${esc(field.label)}<input type="${type}" name="${name}" value="${esc(value)}" ${field.required?'required':''}></label>`;}
function institutionInput(field,value='',values={}){const required=field.required?'required':'',wide=field.width==='wide'?'wide':'',label=`${esc(field.label)}${field.required?' <b>*</b>':''}`,placeholder=esc(field.placeholder||''),name=esc(field.key);if(field.control==='lookup'){const parent=field.lookup_category==='district'?(values.city||null):null,options=lookupItems(field.lookup_category,{parent,current:String(value??'')});return`<label class="${wide}">${label}<select name="${name}" ${required} data-lookup-field="${esc(field.lookup_category)}"><option value="">${placeholder}</option>${options.map(option=>`<option value="${esc(option.item_key)}" ${String(value)===String(option.item_key)?'selected':''}>${esc(option.label)}${option.active?'':' (pasif)'}</option>`).join('')}</select></label>`;}if(field.control==='checkbox')return`<label class="check-label ${wide}"><input type="checkbox" name="${name}" ${value?'checked':''}> ${label}</label>`;if(field.control==='textarea')return`<label class="${wide}">${label}<textarea name="${name}" rows="3" placeholder="${placeholder}" ${required}>${esc(value)}</textarea></label>`;const type=field.control==='number'?'number':field.control==='date'?'date':'text',limits=field.key==='rating'?'min="0" max="5"':field.key==='group_number'||field.key==='sequence_number'?'min="1"':'';return`<label class="${wide}">${label}<input name="${name}" type="${type}" value="${esc(value)}" placeholder="${placeholder}" ${limits} ${required}></label>`;}
function refreshDistrictInput(){const form=$('#institutionForm'),city=form.elements.city,district=form.elements.district;if(!city||!district)return;const current=district.value,field=formField('district');district.innerHTML=`<option value="">${esc(field?.placeholder||'İlçe seçin')}</option>`+lookupItems('district',{parent:city.value,current}).map(option=>`<option value="${esc(option.item_key)}" ${option.item_key===current?'selected':''}>${esc(option.label)}${option.active?'':' (pasif)'}</option>`).join('');}
function setInstitutionPhotoPreview(src=''){const preview=$('#institutionPhotoPreview');preview.innerHTML=src?`<img src="${src}" alt="Kurum fotoğrafı ön izlemesi">`:'<span>Fotoğraf yok</span>';$('#removeInstitutionPhoto').disabled=!src;}
function prepareInstitutionPhoto(item=null){state.institutionPhotoData=null;state.institutionPhotoRemove=false;$('#institutionPhotoInput').value='';const src=item?.photo?`/api/institutions/${encodeURIComponent(item.id)}/photo?v=${encodeURIComponent(item.photo.updated_at||'')}`:'';setInstitutionPhotoPreview(src);}
function readInstitutionPhoto(file){if(!file)return;const allowed=['image/jpeg','image/png','image/webp'];if(!allowed.includes(file.type))return toast('Yalnızca JPG, PNG veya WebP fotoğraf seçebilirsiniz.',true);if(file.size>8*1024*1024)return toast('Kurum fotoğrafı en fazla 8 MB olabilir.',true);const reader=new FileReader();reader.onload=()=>{state.institutionPhotoData={data_url:String(reader.result||''),name:file.name};state.institutionPhotoRemove=false;setInstitutionPhotoPreview(state.institutionPhotoData.data_url);};reader.onerror=()=>toast('Fotoğraf okunamadı.',true);reader.readAsDataURL(file);}
function markInstitutionPhotoForRemoval(){state.institutionPhotoData=null;state.institutionPhotoRemove=true;$('#institutionPhotoInput').value='';setInstitutionPhotoPreview('');}
function openInstitutionForm(item=null){const form=$('#institutionForm');form.reset();$('#institutionDialogTitle').textContent=item?'Kurumu düzenle':'Yeni kurum';const values=item||{};prepareInstitutionPhoto(item);$('#institutionFormGrid').innerHTML=state.institutionFormFields.filter(field=>field.visible).map(field=>institutionInput(field,values[field.key]??field.default_value??'',values)).join('');form.elements.id.value=item?.id||'';form.elements.row_version.value=item?.row_version||'';form.elements.city?.addEventListener('change',refreshDistrictInput);const fields=state.customFields.filter(field=>field.entity_type==='institution');$('#institutionCustomFields').hidden=!fields.length;$('#institutionCustomFieldsGrid').innerHTML=fields.map(field=>customInput(field,(values.custom_values||{})[field.id]||'')).join('');$('#institutionDialog').showModal();}
function formPayload(form){const data={},customValues={};for(const element of form.elements){if(!element.name)continue;let value;if(element.type==='checkbox')value=element.checked;else if(element.multiple)value=[...element.selectedOptions].map(option=>option.value);else value=element.value;if(element.name.startsWith('custom_'))customValues[element.name.slice(7)]=value;else data[element.name]=value;}data.custom_values=customValues;return data;}
async function saveInstitution(event){event.preventDefault();if(!event.currentTarget.reportValidity())return;const data=formPayload(event.currentTarget),id=data.id;delete data.id;if(!data.row_version)delete data.row_version;for(const key of['group_number','sequence_number'])if(data[key]==='')delete data[key];else data[key]=Number(data[key]);try{const saved=(await api(id?`/api/institutions/${encodeURIComponent(id)}`:'/api/institutions',{method:id?'PUT':'POST',body:data})).data,targetId=saved.id||id;let photoError='';try{if(state.institutionPhotoData)await api(`/api/institutions/${encodeURIComponent(targetId)}/photo`,{method:'POST',body:state.institutionPhotoData});else if(state.institutionPhotoRemove&&id)await api(`/api/institutions/${encodeURIComponent(targetId)}/photo`,{method:'DELETE'});}catch(error){photoError=error.message;}$('#institutionDialog').close();await Promise.all([loadFilters(),loadAllInstitutions(),refreshInstitutions()]);if(targetId)await openDetail(targetId);toast(photoError?`Kurum kaydedildi; fotoğraf işlemi tamamlanamadı: ${photoError}`:'Kurum ve fotoğraf bilgileri güvenli biçimde kaydedildi.',Boolean(photoError));}catch(error){toast(error.message,true);}}
async function reloadInstitutionData(){state.selectedInstitutions.clear();closeDrawer();await Promise.all([loadFilters(),loadAllInstitutions(),refreshInstitutions(),loadFinance()]);}
async function archiveInstitutions(ids){const unique=[...new Set(ids.filter(Boolean))];if(!unique.length)return;if(!confirm(`${unique.length} kurum çöp kutusuna taşınacak. Panel ve finans geçmişi korunacak. Devam edilsin mi?`))return;try{const result=(await api('/api/institutions/bulk-delete',{method:'POST',body:{institution_ids:unique}})).data;toast(`${result.archived} kurum çöp kutusuna taşındı.`);await reloadInstitutionData();}catch(error){toast(error.message,true);}}
function updateInstitutionTrashButtons(){const selected=$$('[data-trash-institution]:checked',$('#institutionTrashList')),hasItems=state.archivedInstitutions.length>0;$('#restoreSelectedInstitutions').disabled=!selected.length;$('#purgeSelectedInstitutions').disabled=!selected.length;$('#emptyInstitutionTrash').disabled=!hasItems;}
async function openInstitutionTrash(){const dialog=$('#institutionTrashDialog'),list=$('#institutionTrashList');if(!dialog.open)dialog.showModal();try{state.archivedInstitutions=(await api('/api/institutions/trash')).data;list.innerHTML=state.archivedInstitutions.length?state.archivedInstitutions.map(item=>`<div class="field-row"><input type="checkbox" data-trash-institution="${esc(item.id)}"><span><strong>${esc(item.name)}</strong><small>G${display(item.group_number)} · S${display(item.sequence_number)} · ${esc([item.city,item.district].filter(Boolean).join(' / '))} · ${number(item.panel_count)} panel · ${number(item.finance_value_count)} finans değeri · ${number(item.finance_transaction_count)} hareket</small></span><span class="field-row-actions"><button type="button" data-restore-one-institution="${esc(item.id)}">Geri Yükle</button><button type="button" class="delete-field" data-purge-one-institution="${esc(item.id)}">Kalıcı Sil</button></span></div>`).join(''):'<div class="notice success">Çöp kutusu boş.</div>';updateInstitutionTrashButtons();}catch(error){toast(error.message,true);}}
async function restoreSelectedInstitutions(){return restoreInstitutionsFromTrash($$('[data-trash-institution]:checked',$('#institutionTrashList')).map(input=>input.dataset.trashInstitution));}
async function restoreInstitutionsFromTrash(ids){if(!ids.length)return;try{const result=(await api('/api/institutions/restore',{method:'POST',body:{institution_ids:ids}})).data;toast(`${result.restored} kurum geri yüklendi.`);await openInstitutionTrash();await reloadInstitutionData();}catch(error){toast(error.message,true);}}
async function purgeInstitutions(ids){if(!ids.length)return;const items=state.archivedInstitutions.filter(item=>ids.includes(item.id)),panels=items.reduce((sum,item)=>sum+Number(item.panel_count||0),0),finance=items.reduce((sum,item)=>sum+Number(item.finance_value_count||0),0);const confirmation=prompt(`${ids.length} kurum, ${panels} panel ve ${finance} finans değeri kalıcı olarak silinecek. Bu işlem geri alınamaz. Devam etmek için KALICI SİL yazın.`);if(confirmation!=='KALICI SİL')return;try{const result=(await api('/api/institutions/purge',{method:'POST',body:{institution_ids:ids,confirmation}})).data;toast(`${result.purged} kurum kalıcı olarak silindi.`);await openInstitutionTrash();await reloadInstitutionData();}catch(error){toast(error.message,true);}}
function openPanelForm(panel=null){if(!state.currentInstitution)return;const form=$('#panelForm');form.reset();$('#panelDialogTitle').textContent=panel?'Paneli düzenle':'Panel ekle';const values=panel||{institution_id:state.currentInstitution.id};const status=form.elements.status;if(status)status.innerHTML='<option value=""></option>'+lookupItems('panel_status',{current:values.status||''}).map(item=>`<option value="${esc(item.item_key)}">${esc(item.label)}</option>`).join('');for(const element of form.elements)if(element.name&&values[element.name]!==undefined&&values[element.name]!==null)element.value=values[element.name];$('#panelDialog').showModal();}
async function savePanel(event){event.preventDefault();if(!event.currentTarget.reportValidity())return;const data=formPayload(event.currentTarget);delete data.custom_values;const id=data.id;delete data.id;if(!data.row_version)delete data.row_version;data.turnstile_count=data.turnstile_count===''?null:Number(data.turnstile_count);try{await api(id?`/api/panels/${encodeURIComponent(id)}`:'/api/panels',{method:id?'PUT':'POST',body:data});$('#panelDialog').close();toast('Panel kaydı kaydedildi.');await Promise.all([refreshInstitutions(),openDetail(state.currentInstitution.id)]);}catch(error){toast(error.message,true);}}

function renderColumnSettings(){ $('#columnSettingsList').innerHTML=state.columnDraft.map(column=>`<div class="column-row" draggable="true" data-key="${esc(column.key)}"><span class="column-move"><button type="button" class="drag-handle" title="Sürükleyerek taşı">⠿</button><button type="button">↑</button><button type="button">↓</button></span><label title="Göster / gizle"><input type="checkbox" ${column.visible?'checked':''} ${column.locked?'disabled':''}></label><label class="column-name-control">Alan adı<input type="text" value="${esc(column.label||'İşlemler')}" ${column.key==='actions'?'disabled':''}></label><label class="width-control">Genişlik <input type="number" min="44" max="600" value="${column.width}"> px</label><span class="column-actions"><button type="button" class="pin-column ${column.pinned?'active':''}" title="Sola sabitle">📌</button><button type="button" class="remove-column" ${column.locked?'disabled':''} title="Görünümden kaldır">Sil</button></span></div>`).join('');}
function openColumnSettings(mode='institutions'){state.columnMode=mode;state.columnDraft=(mode==='finance'?state.financeTableColumns:state.tableColumns).map(item=>({...item}));$('#columnDialogTitle').textContent=mode==='finance'?'Finans sütun düzeni':'Kurum tablo sütunları';renderColumnSettings();$('#columnDialog').showModal();}
function readColumnSettings(){return $$('.column-row',$('#columnSettingsList')).map(row=>{const base=state.columnDraft.find(item=>item.key===row.dataset.key);return{...base,label:$('.column-name-control input',row)?.value.trim()||base.label,visible:base.locked?true:$('input[type="checkbox"]',row).checked,pinned:$('.pin-column',row).classList.contains('active'),width:Math.min(600,Math.max(44,Number($('.width-control input',row).value)||base.width))};});}
async function saveColumnSettings(){const columns=readColumnSettings(),finance=state.columnMode==='finance';if(finance)state.financeTableColumns=columns;else state.tableColumns=columns;try{await api(finance?'/api/settings/finance-table-columns':'/api/settings/table-columns',{method:'PUT',body:{columns:columns.map(({key,label,visible,width,pinned})=>({key,label,visible,width,pinned}))}});finance?renderFinanceTable(state.financeData):renderInstitutionTable();$('#columnDialog').close();toast('Sütun adları, sırası, genişliği ve sabitlemesi kaydedildi.');}catch(error){toast(error.message,true);}}
function renderFilterSettings(){const config=state.filterDraft;$('#filterSettingsList').innerHTML=config.map(item=>`<div class="column-row filter-setting" draggable="true" data-key="${esc(item.key)}"><span class="column-move"><button type="button" class="drag-handle" title="Sürükleyerek taşı">⠿</button><button type="button">↑</button><button type="button">↓</button></span><label title="Göster / gizle"><input type="checkbox" ${item.visible?'checked':''}></label><label class="column-name-control">Alan adı<input type="text" value="${esc(item.label)}"></label><label class="width-control">Genişlik <input type="number" min="140" max="500" value="${item.width||180}"> px</label><span class="column-actions"><button type="button" class="pin-column ${item.pinned?'active':''}" title="Öncelikli sırada tut">📌</button><button type="button" class="remove-filter-setting">Sil</button></span></div>`).join('');}
function openFilterSettings(mode='institutions'){state.filterMode=mode;const catalog=mode==='finance'?financeFilterCatalog():filterCatalog();const saved=mode==='finance'?state.financeFilterConfig:state.institutionFilterConfig;state.filterDraft=normalizeFilterConfig(catalog,saved,mode==='institutions'?['city','district','health','status','sales_person']:null).map(item=>({...item}));$('#filterDialogTitle').textContent=mode==='finance'?'Finans filtrelerini ayarla':'Kurum filtrelerini ayarla';renderFilterSettings();$('#filterDialog').showModal();}
function readFilterSettings(){return $$('.filter-setting',$('#filterSettingsList')).map(row=>{const base=state.filterDraft.find(item=>item.key===row.dataset.key);return{...base,label:$('.column-name-control input',row).value.trim()||base.label,visible:$('input[type="checkbox"]',row).checked,width:Math.min(500,Math.max(140,Number($('.width-control input',row).value)||180)),pinned:$('.pin-column',row).classList.contains('active')};});}
async function saveFilterSettings(){const items=readFilterSettings(),finance=state.filterMode==='finance',payload=items.map(({key,label,visible,width,pinned})=>({key,label,visible,width,pinned}));if(finance)state.financeFilterConfig=items;else state.institutionFilterConfig=items;const selections=finance?state.financeSelections:state.institutionSelections;for(const key of Object.keys(selections))if(!items.some(item=>item.key===key&&item.visible))delete selections[key];await api(finance?'/api/settings/finance-filters':'/api/settings/filters',{method:'PUT',body:{filters:payload}});finance?renderFinanceFilters():renderInstitutionFilters();$('#filterDialog').close();toast(`${finance?'Finans':'Kurum'} filtre düzeni kaydedildi.`);finance?await loadFinance():await refreshInstitutions();}

function refreshGroupDistrict(current=''){const city=$('#groupCity').value;$('#groupDistrict').innerHTML='<option value="">İlçe seçin</option>'+lookupItems('district',{parent:city,current}).map(item=>`<option value="${esc(item.item_key)}" ${item.item_key===current?'selected':''}>${esc(item.label)}</option>`).join('');}
function populateGroupForm(group=null){const form=$('#groupForm');form.reset();$('#existingGroup').value=group?.id||'';const values=group||{};$('#groupCity').innerHTML='<option value="">İl seçin</option>'+lookupItems('city',{current:values.city||''}).map(item=>`<option value="${esc(item.item_key)}">${esc(item.label)}</option>`).join('');$('#groupCity').value=values.city||'';refreshGroupDistrict(values.district||'');for(const element of form.elements)if(element.name&&!['institution_ids','city','district'].includes(element.name)&&values[element.name]!==undefined&&values[element.name]!==null)element.value=values[element.name];const members=new Set(group?state.allInstitutions.filter(item=>item.group_number===group.group_number).map(item=>item.id):[]);$('#groupInstitutions').innerHTML=state.allInstitutions.map(item=>`<option value="${esc(item.id)}" ${members.has(item.id)?'selected':''}>G${display(item.group_number)} · S${display(item.sequence_number)} · ${esc(item.name)}</option>`).join('');$('#deleteGroup').hidden=!group;}
function openGroupManager(groupId=''){const select=$('#existingGroup');select.innerHTML='<option value="">Yeni grup oluştur</option>'+state.groups.map(group=>`<option value="${esc(group.id)}">${group.group_number} · ${esc(group.name)}</option>`).join('');const group=state.groups.find(item=>item.id===groupId)||null;populateGroupForm(group);$('#groupDialog').showModal();}
async function saveGroup(event){event.preventDefault();if(!event.currentTarget.reportValidity())return;const data=formPayload(event.currentTarget),id=data.id;delete data.id;delete data.custom_values;if(!data.row_version)delete data.row_version;if(!data.group_number)delete data.group_number;try{await api(id?`/api/groups/${encodeURIComponent(id)}`:'/api/groups',{method:id?'PUT':'POST',body:data});$('#groupDialog').close();toast('Çatı kurum ve alt kurum bağlantıları kaydedildi.');await Promise.all([loadAllInstitutions(),refreshInstitutions(),loadFinance()]);}catch(error){toast(error.message,true);}}
async function deleteGroup(groupId=''){const id=groupId||$('#groupForm').elements.id.value,group=state.groups.find(item=>item.id===id);if(!id||!group)return;if(!confirm(`${group.group_number} · ${group.name} grubu kaldırılacak. İçindeki kurumlar silinmeyecek ve bağımsız hâle getirilecek. Devam edilsin mi?`))return;try{await api(`/api/groups/${encodeURIComponent(id)}`,{method:'DELETE'});$('#groupDialog').close();toast('Grup kaldırıldı; kurumlar ve kayıtları korundu.');await Promise.all([loadAllInstitutions(),refreshInstitutions(),loadFinance()]);}catch(error){toast(error.message,true);}}

function financeFieldValue(field,value){if(value===null||value===undefined||value==='')return'—';if(['money','formula'].includes(field.data_type))return new Intl.NumberFormat('tr-TR',{style:'currency',currency:'TRY'}).format(decimal(value));if(field.data_type==='number')return number(decimal(value));if(field.data_type==='multiselect'){try{return JSON.parse(value).join(', ');}catch{return value;}}return esc(value);}
function aggregateValues(values,operation='sum'){const numeric=values.map(decimal);if(operation==='count')return values.filter(value=>String(value??'').trim()!=='').length;if(!numeric.length)return 0;if(operation==='avg')return numeric.reduce((a,b)=>a+b,0)/numeric.length;if(operation==='min')return Math.min(...numeric);if(operation==='max')return Math.max(...numeric);return numeric.reduce((a,b)=>a+b,0);}
function aggregateGroupValue(group,field){if(field.aggregate_type==='none')return'';return aggregateValues(group.children.map(row=>(row.finance_values||{})[field.field_key]),field.aggregate_type);}
function financeCell(column,item,group=null,child=false,listNo=''){if(group&&!item){switch(column.key){case'list_number':return`<span class="number-badge sequence">${esc(listNo)}</span>`;case'group_number':return`<div class="tree-group-cell"><button class="tree-toggle" type="button" data-toggle-finance-group="${esc(group.id)}">${state.expandedFinanceGroups.has(group.id)?'−':'+'}</button><span class="number-badge group">${number(group.group_number)}</span></div>`;case'institution':return`<div class="institution-cell group-title"><strong>${esc(group.name)}</strong><span>${number(group.children.length)} alt kurum</span></div>`;case'city':return`${display(lookupLabel('city',group.children[0].city))}<span class="subtext">${display(lookupLabel('district',group.children[0].district),'')}</span>`;case'actions':return'';default:if(column.key.startsWith('finance:')){const field=state.financeFields.find(item=>item.field_key===column.key.slice(8));return field?`<strong>${financeFieldValue(field,aggregateGroupValue(group,field))}</strong>`:'';}return'';}}
  switch(column.key){case'list_number':return`<span class="number-badge sequence">${esc(listNo)}</span>`;case'group_number':return`<span class="number-badge group">${display(item.group_number)}</span>`;case'sequence_number':return`<span class="number-badge sequence">${display(item.sequence_number)}</span>`;case'institution':return`<div class="institution-cell ${child?'child-cell':''}"><strong>${esc(item.name)}</strong><span>${display(lookupLabel('school_type',item.school_type),'')}</span></div>`;case'city':return`${display(lookupLabel('city',item.city))}<span class="subtext">${display(lookupLabel('district',item.district),'')}</span>`;case'sales_person':return display(lookupLabel('sales_person',item.sales_person));case'actions':return`<button data-finance-institution="${esc(item.id)}">Düzenle</button>`;default:if(column.key.startsWith('finance:')){const field=state.financeFields.find(field=>field.field_key===column.key.slice(8));return field?financeFieldValue(field,(item.finance_values||{})[field.field_key]):'';}return'';}}
function renderFinanceTable(data){if(!data)return;const visible=stickyColumns(state.financeTableColumns.filter(column=>column.visible));$('#financeHead').innerHTML=visible.map(column=>`<th${cellAttrs(column,column.key==='actions'?'row-actions':'')}>${esc(column.label)}</th>`).join('');$('#financeTable').style.minWidth=`${visible.reduce((sum,column)=>sum+column.width,0)}px`;const rows=[];data.groups.forEach((group,groupIndex)=>{const parentNo=groupIndex+1;if(group.children.length===1)rows.push(financeRow(group.children[0],visible,false,parentNo));else{rows.push(`<tr class="group-row">${visible.map(column=>`<td${cellAttrs(column,column.key==='actions'?'row-actions':'')}>${financeCell(column,null,group,false,parentNo)}</td>`).join('')}</tr>`);if(state.expandedFinanceGroups.has(group.id))group.children.forEach((item,childIndex)=>rows.push(financeRow(item,visible,true,`${parentNo}.${childIndex+1}`)));}});$('#financeBody').innerHTML=rows.join('');$('#financeTotals').innerHTML=visible.map(column=>{let content='';if(column.key==='institution')content=`GENEL TOPLAM · ${number(data.record_total)} kayıt`;else if(column.key.startsWith('finance:')){const key=column.key.slice(8),field=state.financeFields.find(item=>item.field_key===key),aggregate=data.aggregates?.[key];if(field&&aggregate)content=financeFieldValue(field,aggregate.value);}return`<td${cellAttrs(column,column.key==='actions'?'row-actions':'')}>${content}</td>`;}).join('');$('#financeEmpty').hidden=data.groups.length!==0;requestAnimationFrame(refreshTopScrollbars);}
function financeRow(item,visible,child,listNo){return`<tr class="${child?'child-row':''}">${visible.map(column=>`<td${cellAttrs(column,column.key==='actions'?'row-actions':'')}>${financeCell(column,item,null,child,listNo)}</td>`).join('')}</tr>`;}
function financeCardValue(card,summary){let value=0;if(card.metric==='institution_count')value=summary.institution_count;else if(card.metric==='record_count')value=summary.record_count;else if(card.metric.startsWith('field:'))value=summary.field_aggregates?.[card.metric.slice(6)]?.value||0;if(card.format==='money')return new Intl.NumberFormat('tr-TR',{style:'currency',currency:'TRY'}).format(decimal(value));if(card.format==='percent')return`${new Intl.NumberFormat('tr-TR',{maximumFractionDigits:2}).format(decimal(value))}%`;return number(decimal(value));}
function renderFinanceSummaryCards(summary){const cards=(state.financeSummaryCards.length?state.financeSummaryCards:DEFAULT_FINANCE_CARDS).filter(card=>card.visible);$('#financeSummaryCards').innerHTML=cards.map(card=>`<article class="kpi ${esc(card.color||'neutral')}"><span>${esc(card.label)}</span><strong>${esc(financeCardValue(card,summary))}</strong><small>${esc(card.subtitle||'Filtrelenmiş sonuç')}</small></article>`).join('')||'<div class="notice">Görünür finans kartı yok. Kartlar düğmesinden ekleyebilirsiniz.</div>';}
async function loadFinance(refreshFilterUi=true){const params=financeParams(),suffix=params.toString()?`?${params}`:'';try{const[summaryResult,listResult]=await Promise.all([api(`/api/finance/dashboard${suffix}`),api(`/api/finance/institutions${suffix}`)]);const summary=summaryResult.data,data=listResult.data;state.financeData=data;state.financeFields=data.fields;state.financeTableColumns=mergeFinanceColumns(state.financeTableColumns);renderFinanceSummaryCards(summary);$('#financeResultCount').textContent=`${number(data.total)} kurum · ${number(data.record_total)} alt kayıt`;if(refreshFilterUi)renderFinanceFilters();renderFinanceTable(data);}catch(error){toast(error.message,true);}}
function financeInput(field,value=''){const name=`finance_${field.id}`;if(field.data_type==='formula')return`<label>${esc(field.label)}<input value="${esc(value)}" readonly><span class="field-help">${esc(field.formula)}</span></label>`;if(field.data_type==='list')return`<label>${esc(field.label)}<select name="${name}"><option value=""></option>${field.options.map(option=>`<option ${String(value)===String(option)?'selected':''}>${esc(option)}</option>`).join('')}</select></label>`;if(field.data_type==='multiselect'){let selected=[];try{selected=JSON.parse(value||'[]');}catch{}return`<label>${esc(field.label)}<select name="${name}" multiple>${field.options.map(option=>`<option ${selected.includes(option)?'selected':''}>${esc(option)}</option>`).join('')}</select></label>`;}if(field.data_type==='boolean')return`<label>${esc(field.label)}<select name="${name}"><option value=""></option><option ${value==='Evet'?'selected':''}>Evet</option><option ${value==='Hayır'?'selected':''}>Hayır</option></select></label>`;const type=field.data_type==='date'?'date':field.data_type==='number'?'number':'text';return`<label>${esc(field.label)}<input type="${type}" step="any" name="${name}" value="${esc(value)}"></label>`;}
function openFinanceValues(id){const item=state.financeData.items.find(row=>row.id===id);if(!item)return;const form=$('#financeValuesForm');form.reset();form.elements.institution_id.value=id;$('#financeValuesTitle').textContent=item.name;$('#financeValuesGrid').innerHTML=state.financeFields.map(field=>financeInput(field,(item.finance_values||{})[field.field_key]||'')).join('');$('#financeValuesDialog').showModal();}
async function saveFinanceValues(event){event.preventDefault();const values={};for(const element of event.currentTarget.elements)if(element.name&&element.name.startsWith('finance_'))values[element.name.slice(8)]=element.multiple?[...element.selectedOptions].map(option=>option.value):element.value;const id=event.currentTarget.elements.institution_id.value;try{await api(`/api/finance/institutions/${encodeURIComponent(id)}/values`,{method:'POST',body:{values}});$('#financeValuesDialog').close();toast('Finans bilgileri ve formüller güncellendi.');await loadFinance();}catch(error){toast(error.message,true);}}
function updateFinanceFieldSelectionUi(){const selected=$$('[data-select-finance-field]:checked',$('#financeFieldList'));$('#deleteSelectedFinanceFields').disabled=!selected.length;$('#deleteSelectedFinanceFields').textContent=selected.length?`${selected.length} Alanı Sil`:'Seçilenleri Sil';$('#selectAllFinanceFields').checked=Boolean(state.financeFields.length)&&selected.length===state.financeFields.length;}
function renderFinanceFieldList(){$('#financeFieldList').innerHTML=state.financeFields.map(field=>`<div class="field-row" draggable="true" data-field-id="${esc(field.id)}"><button type="button" class="drag-handle field-drag" title="Sürükleyerek taşı">⠿</button><span class="column-move"><button type="button" data-move-field="up">↑</button><button type="button" data-move-field="down">↓</button></span><input type="checkbox" data-select-finance-field="${esc(field.id)}"><button type="button" class="field-row-main" data-edit-finance-field="${esc(field.id)}"><strong>${esc(field.label)} ${field.data_type==='formula'?'<span class="badge blue">ƒx</span>':''}</strong><small>${esc(field.field_key)} · ${esc(field.data_type)} · ${field.aggregate_type!=='none'?`Toplam: ${esc(field.aggregate_type)}`:'Toplamsız'} · ${field.visible?'Görünür':'Gizli'} · ${field.filterable?'Filtreli':'Filtresiz'}${field.system_field?' · Hazır alan':''}</small></button><span class="field-row-actions"><button type="button" data-edit-finance-field="${esc(field.id)}">Düzenle ✎</button><button type="button" class="delete-field" data-delete-finance-field="${esc(field.id)}">Sil 🗑</button></span></div>`).join('');updateFinanceFieldSelectionUi();}
async function openFinanceFields(){renderFinanceFieldList();$('#financeFieldForm').hidden=true;$('#financeFieldTrash').hidden=true;$('#financeFieldsDialog').showModal();await loadArchivedFinanceFields();}
function editFinanceField(field=null){const form=$('#financeFieldForm');form.hidden=false;form.reset();const values=field||{visible:1,filterable:1,active:1,decimal_places:2,aggregate_type:'none'};for(const element of form.elements)if(element.name&&values[element.name]!==undefined){if(element.type==='checkbox')element.checked=Boolean(values[element.name]);else if(element.name==='options')element.value=(values.options||[]).join(', ');else element.value=values[element.name]??'';}form.elements.field_key.disabled=Boolean(field);$('#formulaFieldPicker').innerHTML='<option value="">Formüle alan ekle…</option>'+state.financeFields.filter(item=>!field||item.id!==field.id).map(item=>`<option value="${esc(item.field_key)}">${esc(item.label)} · ${esc(item.field_key)}</option>`).join('');form.scrollIntoView({behavior:'smooth',block:'nearest'});}
async function saveFinanceField(event){event.preventDefault();if(!event.currentTarget.reportValidity())return;const data=formPayload(event.currentTarget),id=data.id;delete data.id;delete data.custom_values;data.options=data.options.split(',').map(value=>value.trim()).filter(Boolean);try{await api(id?`/api/finance/fields/${encodeURIComponent(id)}`:'/api/finance/fields',{method:id?'PUT':'POST',body:data});state.financeFields=(await api('/api/finance/fields')).data;renderFinanceFieldList();event.currentTarget.hidden=true;toast('Finans alanı kaydedildi.');await loadFinance();}catch(error){toast(error.message,true);}}
async function saveFinanceFieldOrder(){const ids=$$('[data-field-id]',$('#financeFieldList')).map(row=>row.dataset.fieldId);try{state.financeFields=(await api('/api/finance/fields/reorder',{method:'POST',body:{field_ids:ids}})).data;renderFinanceFieldList();await loadFinance();toast('Finans alanı sırası kaydedildi.');}catch(error){toast(error.message,true);}}
async function archiveFinanceFields(ids){const unique=[...new Set(ids.filter(Boolean))];if(!unique.length)return;if(!confirm(`${unique.length} finans alanı silinen alanlara taşınacak. Kayıtlı değerler korunacak. Devam edilsin mi?`))return;try{const result=(await api('/api/finance/fields/bulk-delete',{method:'POST',body:{field_ids:unique}})).data;toast(`${result.archived} finans alanı arşivlendi.`);state.financeFields=(await api('/api/finance/fields')).data;state.financeTableColumns=mergeFinanceColumns(state.financeTableColumns);renderFinanceFieldList();await Promise.all([loadArchivedFinanceFields(),loadFinance()]);}catch(error){toast(error.message,true);}}
async function loadArchivedFinanceFields(){state.archivedFinanceFields=(await api('/api/finance/fields/trash')).data;$('#financeFieldTrash').innerHTML=state.archivedFinanceFields.length?`<strong>Silinen alanlar</strong>${state.archivedFinanceFields.map(field=>`<div class="field-row"><span><strong>${esc(field.label)}</strong><small>${esc(field.field_key)} · ${esc(field.data_type)}${field.system_field?' · Hazır alan':''}</small></span><span class="field-row-actions"><button type="button" data-restore-finance-field="${esc(field.id)}">Geri Yükle</button><button type="button" class="delete-field" data-purge-finance-field="${esc(field.id)}" ${field.system_field?'disabled title="Hazır alan kalıcı silinemez"':''}>Kalıcı Sil</button></span></div>`).join('')}`:'<div class="notice success">Silinen finans alanı yok.</div>';}
async function restoreFinanceField(id){try{await api('/api/finance/fields/restore',{method:'POST',body:{field_ids:[id]}});toast('Finans alanı geri yüklendi.');state.financeFields=(await api('/api/finance/fields')).data;state.financeTableColumns=mergeFinanceColumns(state.financeTableColumns);renderFinanceFieldList();await Promise.all([loadArchivedFinanceFields(),loadFinance()]);}catch(error){toast(error.message,true);}}
async function purgeFinanceField(id){const field=state.archivedFinanceFields.find(item=>item.id===id);if(!field)return;const confirmation=prompt(`${field.label} alanı ve bu alandaki bütün kayıtlı değerler kalıcı silinecek. Devam etmek için KALICI SİL yazın.`);if(confirmation!=='KALICI SİL')return;try{const result=(await api('/api/finance/fields/purge',{method:'POST',body:{field_ids:[id],confirmation}})).data;toast(`${result.purged} finans alanı kalıcı silindi.`);await loadArchivedFinanceFields();}catch(error){toast(error.message,true);}}

function commissionFieldOptions(){return[{field_key:'city',label:fieldLabel('city','Şehir'),lookup_category:'city'},{field_key:'district',label:fieldLabel('district','İlçe'),lookup_category:'district'},{field_key:'sales_person',label:fieldLabel('sales_person','Satış temsilcisi'),lookup_category:'sales_person'},{field_key:'customer_status',label:fieldLabel('customer_status','Satış durumu'),lookup_category:'customer_status'},{field_key:'payment_status',label:fieldLabel('payment_status','Ödeme durumu'),lookup_category:'payment_status'},{field_key:'health_status',label:fieldLabel('health_status','Çalışma durumu'),lookup_category:'health_status'},...state.financeFields];}
function conditionValueControl(fieldKey,value=''){const field=commissionFieldOptions().find(item=>item.field_key===fieldKey);if(field?.lookup_category)return`<select data-condition-value><option value="">Değer seçin</option>${lookupItems(field.lookup_category).map(item=>`<option value="${esc(item.item_key)}" ${String(value)===String(item.item_key)?'selected':''}>${esc(item.label)}</option>`).join('')}</select>`;return`<input data-condition-value value="${esc(value)}" placeholder="Ölçüt">`;}
function addConditionRow(value={}){const fields=commissionFieldOptions(),fieldKey=value.field||fields[0]?.field_key||'';$('#commissionConditions').insertAdjacentHTML('beforeend',`<div class="condition-row"><select data-condition-field>${fields.map(field=>`<option value="${esc(field.field_key)}" ${fieldKey===field.field_key?'selected':''}>${esc(field.label)}</option>`).join('')}</select><select data-condition-operator><option value="eq">Eşittir</option><option value="neq">Eşit değildir</option><option value="contains">İçerir</option><option value="gte">Büyük/eşit</option><option value="lte">Küçük/eşit</option><option value="gt">Büyüktür</option><option value="lt">Küçüktür</option></select><span data-condition-value-wrap>${conditionValueControl(fieldKey,value.value||'')}</span><button type="button" class="icon-button" data-remove-condition>×</button></div>`);if(value.operator)$('[data-condition-operator]',$('#commissionConditions').lastElementChild).value=value.operator;}
function openCommissionRule(rule=null){state.editingCommissionRule=rule;const form=$('#commissionForm');form.reset();$('#commissionBaseField').innerHTML=commissionFieldOptions().map(field=>`<option value="${esc(field.field_key)}">${esc(field.label)}</option>`).join('');$('#commissionSalesPerson').innerHTML='<option value="">Tüm temsilciler</option>'+lookupItems('sales_person').map(item=>`<option value="${esc(item.item_key)}">${esc(item.label)}</option>`).join('');if(rule){for(const element of form.elements)if(element.name&&rule[element.name]!==undefined)element.value=element.name==='rate'?rule.rate_text:rule[element.name];}$('#commissionConditions').innerHTML='';for(const condition of rule?.conditions||[{}])addConditionRow(condition);$('#commissionDialog').showModal();}
async function loadCommissionRules(){state.commissionRules=(await api('/api/commissions/rules')).data;$('#commissionRuleCount').textContent=number(state.commissionRules.length);$('#commissionRules').innerHTML=state.commissionRules.length?state.commissionRules.map(rule=>`<button type="button" class="rule-card" data-edit-commission="${esc(rule.id)}"><strong>${esc(rule.name)}</strong><span>${esc(rule.sales_person||'Tüm temsilciler')} · ${esc(rule.base_field_key)} · ${esc(rule.calculation_type)} ${esc(rule.rate_text)}</span><small>${number(rule.conditions.length)} koşul · Düzenlemek için açın</small></button>`).join(''):'<div class="notice">Henüz prim kuralı oluşturulmadı.</div>';}
async function saveCommissionRule(event){event.preventDefault();if(!event.currentTarget.reportValidity())return;const data=formPayload(event.currentTarget);delete data.custom_values;data.conditions=$$('.condition-row',$('#commissionConditions')).map(row=>({field:$('[data-condition-field]',row).value,operator:$('[data-condition-operator]',row).value,value:$('[data-condition-value]',row).value})).filter(item=>item.value!=='');const current=state.editingCommissionRule;if(current)data.row_version=current.row_version;try{await api(current?`/api/commissions/rules/${encodeURIComponent(current.id)}`:'/api/commissions/rules',{method:current?'PUT':'POST',body:data});$('#commissionDialog').close();state.editingCommissionRule=null;toast('Prim kuralı kaydedildi.');await loadCommissionRules();}catch(error){toast(error.message,true);}}
async function calculateCommission(){try{const filters={};for(const[key,values]of financeParams().entries()){if(filters[key])filters[key]=[].concat(filters[key],values);else filters[key]=values;}const result=(await api('/api/commissions/calculate',{method:'POST',body:{filters}})).data;$('#commissionTotal').textContent=money(result.total_minor);$('#commissionResults').innerHTML=result.items.length?result.items.map(item=>`<div class="history-row"><div><strong>${esc(item.institution_name)}</strong><span>${esc(item.rule_name)} · ${esc(item.sales_person||'Temsilci yok')}</span></div><div><strong>${money(item.amount_minor)}</strong><span>Taban: ${esc(item.base)} · Oran: ${esc(item.rate)}</span></div></div>`).join(''):'<div class="notice">Tanımlı koşullara uyan kurum bulunamadı.</div>';toast(`${number(result.institution_count)} kurum için prim hesaplandı.`);}catch(error){toast(error.message,true);}}

function renderInstitutionFormSettings(){const list=$('#institutionFormSettingsList');list.innerHTML=state.institutionFormDraft.map(field=>`<div class="form-setting-row" draggable="true" data-form-key="${esc(field.key)}"><span class="column-move"><button type="button" class="drag-handle" title="Sürükleyerek taşı">⠿</button><button type="button" data-config-move="up">↑</button><button type="button" data-config-move="down">↓</button></span><label>Alan adı<input data-form-label value="${esc(field.label)}"></label><label>Genişlik<select data-form-width><option value="half" ${field.width!=='wide'?'selected':''}>Yarım</option><option value="wide" ${field.width==='wide'?'selected':''}>Tam</option></select></label><label>Varsayılan<input data-form-default value="${esc(field.default_value??'')}"></label><label>Yer tutucu<input data-form-placeholder value="${esc(field.placeholder||'')}"></label><span><label class="check-label"><input type="checkbox" data-form-required ${field.required?'checked':''}> Zorunlu</label><label class="check-label"><input type="checkbox" data-form-visible ${field.visible?'checked':''}> Göster</label><button type="button" class="delete-field text-button" data-hide-form-field>Kaldır</button></span></div>`).join('');}
function openInstitutionFormSettings(){state.institutionFormDraft=structuredClone(state.institutionFormFields);renderInstitutionFormSettings();$('#institutionFormSettingsDialog').showModal();}
function readInstitutionFormSettings(){return $$('[data-form-key]',$('#institutionFormSettingsList')).map(row=>{const base=state.institutionFormDraft.find(item=>item.key===row.dataset.formKey);return{...base,label:$('[data-form-label]',row).value.trim()||base.label,width:$('[data-form-width]',row).value,default_value:$('[data-form-default]',row).value,placeholder:$('[data-form-placeholder]',row).value,required:$('[data-form-required]',row).checked,visible:$('[data-form-visible]',row).checked};});}
async function saveInstitutionFormSettings(){try{state.institutionFormFields=(await api('/api/settings/institution-form',{method:'PUT',body:{fields:readInstitutionFormSettings()}})).data;$('#institutionFormSettingsDialog').close();toast('Kurum formu güvenli biçimde güncellendi.');renderInstitutionFilters();}catch(error){toast(error.message,true);}}
async function resetInstitutionFormSettings(){if(!confirm('Kurum formu varsayılan alan düzenine döndürülsün mü?'))return;try{state.institutionFormFields=(await api('/api/settings/institution-form',{method:'PUT',body:{fields:[]}})).data;state.institutionFormDraft=structuredClone(state.institutionFormFields);renderInstitutionFormSettings();toast('Kurum formu varsayılana döndü.');}catch(error){toast(error.message,true);}}

function selectedLookupCategory(){return lookupCategory($('#lookupCategorySelect').value)||state.lookupCategories[0];}
function renderLookupCategoryOptions(selected=''){const select=$('#lookupCategorySelect');select.innerHTML=state.lookupCategories.map(category=>`<option value="${esc(category.category_key)}" ${category.category_key===selected?'selected':''}>${esc(category.label)}</option>`).join('');}
function renderLookupItems(){const category=selectedLookupCategory();if(!category)return;$('#lookupCategoryLabel').value=category.label;const parentCategory=category.parent_category_key?lookupCategory(category.parent_category_key):null;$('#lookupItemList').innerHTML=(category.items||[]).map(item=>`<div class="field-row ${item.active?'':'archived-row'}" draggable="${item.active?'true':'false'}" data-lookup-id="${esc(item.id)}"><button type="button" class="drag-handle field-drag" ${item.active?'':'disabled'}>⠿</button>${item.color?`<i class="lookup-color" style="background:${esc(item.color)}"></i>`:''}<button class="field-row-main" type="button" data-edit-lookup="${esc(item.id)}"><strong>${esc(item.label)} ${item.active?'':'<span class="badge">Pasif</span>'}</strong><small>${parentCategory&&item.parent_item_key?`${esc(parentCategory.label)}: ${esc(lookupLabel(parentCategory.category_key,item.parent_item_key))} · `:''}${number(item.usage_count)} kayıtta kullanılıyor</small></button><span class="field-row-actions">${item.active?`<button type="button" data-merge-lookup="${esc(item.id)}">Birleştir</button><button type="button" class="delete-field" data-archive-lookup="${esc(item.id)}">Kaldır</button>`:`<button type="button" data-restore-lookup="${esc(item.id)}">Geri Yükle</button>`}</span></div>`).join('')||'<div class="notice">Bu grupta henüz tanım yok.</div>';}
async function openLookupManager(categoryKey=''){await loadLookups();renderLookupCategoryOptions(categoryKey||state.lookupCategories[0]?.category_key);renderLookupItems();$('#lookupItemForm').hidden=true;$('#lookupDialog').showModal();}
function editLookupItem(item=null){const category=selectedLookupCategory(),form=$('#lookupItemForm');state.editingLookupItem=item;form.hidden=false;form.reset();form.elements.id.value=item?.id||'';form.elements.category_key.value=category.category_key;form.elements.label.value=item?.label||'';form.elements.color.value=item?.color||'#15865d';form.elements.active.checked=item?Boolean(item.active):true;const parentWrap=$('#lookupParentWrap'),parentSelect=form.elements.parent_item_key;parentWrap.hidden=!category.parent_category_key;if(category.parent_category_key){parentSelect.innerHTML='<option value="">Üst değer seçin</option>'+lookupItems(category.parent_category_key).map(parent=>`<option value="${esc(parent.item_key)}">${esc(parent.label)}</option>`).join('');parentSelect.value=item?.parent_item_key||'';}form.scrollIntoView({behavior:'smooth',block:'nearest'});}
async function saveLookupItem(event){event.preventDefault();if(!event.currentTarget.reportValidity())return;const data=formPayload(event.currentTarget),id=data.id;delete data.id;delete data.custom_values;try{await api(id?`/api/lookups/items/${encodeURIComponent(id)}`:'/api/lookups/items',{method:id?'PUT':'POST',body:data});const category=data.category_key;await Promise.all([loadLookups(),loadFilters()]);renderLookupCategoryOptions(category);renderLookupItems();event.currentTarget.hidden=true;renderInstitutionFilters();renderFinanceFilters();toast('Tanım değeri kaydedildi; ilgili ekranlar güncellendi.');}catch(error){toast(error.message,true);}}
async function archiveLookupItem(id){const item=selectedLookupCategory()?.items.find(entry=>entry.id===id);if(!item||!confirm(`${item.label} listeden kaldırılacak. ${number(item.usage_count)} mevcut kayıttaki değer korunacak. Devam edilsin mi?`))return;try{await api(`/api/lookups/items/${encodeURIComponent(id)}`,{method:'DELETE'});const category=item.category_key;await Promise.all([loadLookups(),loadFilters()]);renderLookupCategoryOptions(category);renderLookupItems();toast('Tanım pasife alındı; eski kayıtlar korundu.');}catch(error){toast(error.message,true);}}
async function restoreLookupItem(id){try{await api('/api/lookups/items/restore',{method:'POST',body:{item_ids:[id]}});const category=$('#lookupCategorySelect').value;await Promise.all([loadLookups(),loadFilters()]);renderLookupCategoryOptions(category);renderLookupItems();toast('Tanım geri yüklendi.');}catch(error){toast(error.message,true);}}
async function mergeLookupItem(id){const category=selectedLookupCategory(),source=category.items.find(item=>item.id===id),targets=category.items.filter(item=>item.active&&item.id!==id&&item.parent_item_key===source.parent_item_key);if(!targets.length)return toast('Birleştirilebilecek başka aktif değer yok.',true);const requested=prompt(`“${source.label}” hangi değerle birleştirilsin?\n${targets.map(item=>item.label).join(' · ')}`);if(!requested)return;const target=targets.find(item=>item.label.toLocaleLowerCase('tr-TR')===requested.trim().toLocaleLowerCase('tr-TR'));if(!target)return toast('Hedef değer bulunamadı; adı listede göründüğü gibi yazın.',true);try{const result=(await api('/api/lookups/items/merge',{method:'POST',body:{source_id:id,target_id:target.id}})).data;await Promise.all([loadLookups(),loadFilters(),reloadInstitutionData()]);renderLookupCategoryOptions(category.category_key);renderLookupItems();toast(`${number(result.changed_records)} kayıt birleştirildi.`);}catch(error){toast(error.message,true);}}
async function saveLookupOrder(){const category=selectedLookupCategory(),ids=$$('[data-lookup-id][draggable="true"]',$('#lookupItemList')).map(row=>row.dataset.lookupId);try{await api('/api/lookups/items/reorder',{method:'POST',body:{category_key:category.category_key,item_ids:ids}});await loadLookups();renderLookupCategoryOptions(category.category_key);renderLookupItems();toast('Tanım sırası kaydedildi.');}catch(error){toast(error.message,true);}}
async function saveLookupCategory(){const category=selectedLookupCategory(),label=$('#lookupCategoryLabel').value.trim();if(!label)return;try{await api(`/api/lookups/categories/${encodeURIComponent(category.category_key)}`,{method:'PUT',body:{label}});await loadLookups();renderLookupCategoryOptions(category.category_key);renderLookupItems();toast('Tanım grubu adı güncellendi.');}catch(error){toast(error.message,true);}}

function financeCardMetrics(){return[{value:'institution_count',label:'Kurum sayısı'},{value:'record_count',label:'Alt kayıt sayısı'},...state.financeFields.filter(field=>field.aggregate_type!=='none').map(field=>({value:`field:${field.field_key}`,label:`${field.label} · ${field.aggregate_type}`}))];}
function renderFinanceCardList(){const list=$('#financeCardList');list.innerHTML=state.financeCardDraft.map(card=>`<div class="field-row" draggable="true" data-card-id="${esc(card.id)}"><button type="button" class="drag-handle field-drag">⠿</button><button type="button" class="field-row-main" data-edit-finance-card="${esc(card.id)}"><strong>${esc(card.label)} ${card.visible?'':'<span class="badge">Gizli</span>'}</strong><small>${esc(financeCardMetrics().find(item=>item.value===card.metric)?.label||card.metric)} · ${esc(card.format)} · ${esc(card.color)}</small></button><span class="field-row-actions"><button type="button" data-edit-finance-card="${esc(card.id)}">Düzenle</button><button type="button" class="delete-field" data-delete-finance-card="${esc(card.id)}">Sil</button></span></div>`).join('')||'<div class="notice">Kart yok. Yeni kart ekleyebilirsiniz.</div>';}
function openFinanceCards(){state.financeCardDraft=structuredClone(state.financeSummaryCards.length?state.financeSummaryCards:DEFAULT_FINANCE_CARDS);renderFinanceCardList();$('#financeCardForm').hidden=true;$('#financeCardsDialog').showModal();}
function editFinanceCard(card=null){const form=$('#financeCardForm');state.editingFinanceCard=card;form.hidden=false;form.reset();$('#financeCardMetric').innerHTML=financeCardMetrics().map(item=>`<option value="${esc(item.value)}">${esc(item.label)}</option>`).join('');const values=card||{id:`card_${Date.now()}`,label:'Yeni Kart',metric:'institution_count',format:'number',color:'neutral',subtitle:'Filtrelenmiş sonuç',visible:true};for(const element of form.elements)if(element.name&&values[element.name]!==undefined){if(element.type==='checkbox')element.checked=Boolean(values[element.name]);else element.value=values[element.name];}form.scrollIntoView({behavior:'smooth',block:'nearest'});}
function saveFinanceCardDraft(event){event.preventDefault();const data=formPayload(event.currentTarget);delete data.custom_values;const index=state.financeCardDraft.findIndex(item=>item.id===data.id);if(index>=0)state.financeCardDraft[index]=data;else state.financeCardDraft.push(data);event.currentTarget.hidden=true;renderFinanceCardList();}
function readFinanceCardOrder(){const byId=new Map(state.financeCardDraft.map(item=>[item.id,item]));return $$('[data-card-id]',$('#financeCardList')).map(row=>byId.get(row.dataset.cardId)).filter(Boolean);}
async function persistFinanceCards(){try{state.financeSummaryCards=(await api('/api/settings/finance-summary-cards',{method:'PUT',body:{cards:readFinanceCardOrder()}})).data;state.financeCardDraft=structuredClone(state.financeSummaryCards);$('#financeCardsDialog').close();await loadFinance();toast('Finans özet kartları kaydedildi.');}catch(error){toast(error.message,true);}}
function deleteFinanceCard(id){state.financeCardDraft=state.financeCardDraft.filter(item=>item.id!==id);renderFinanceCardList();}
function resetFinanceCards(){state.financeCardDraft=structuredClone(DEFAULT_FINANCE_CARDS);renderFinanceCardList();toast('Varsayılan kartlar ön izlemeye alındı; kaydetmeyi unutmayın.');}

function financeViewConditions(view){const catalog=financeFilterCatalog(),entries=[];if(view.search)entries.push(`Arama: ${view.search}`);for(const[key,values]of Object.entries(view.selections||{})){if(!values?.length)continue;const item=catalog.find(entry=>entry.key===key),labels=values.map(value=>optionLabel(item||{values:[]},value));entries.push(`${item?.label||key}: ${labels.join(', ')}`);}for(const[key,range]of Object.entries(view.ranges||{})){if(!range?.min&&!range?.max)continue;const item=catalog.find(entry=>entry.key===key);entries.push(`${item?.label||key}: ${range.min||'…'} – ${range.max||'…'}`);}return entries;}
function currentFinanceViewSnapshot(name=''){return{id:`gorunum_${Date.now()}`,name,search:$('#financeSearch').value.trim(),selections:structuredClone(state.financeSelections),ranges:structuredClone(state.financeRanges),columns:state.financeTableColumns.map(({key,label,visible,width,pinned})=>({key,label,visible,width,pinned})),is_default:false};}
function renderCurrentFinanceViewSummary(){const snapshot=currentFinanceViewSnapshot(),conditions=financeViewConditions(snapshot),visible=snapshot.columns.filter(item=>item.visible).length;$('#currentFinanceViewSummary').innerHTML=(conditions.length?conditions.map(item=>`<span>${esc(item)}</span>`).join(''):'<span>Filtre veya arama seçilmedi</span>')+`<span>${number(visible)} görünür sütun</span>`;}
function updateActiveFinanceViewBanner(){const banner=$('#activeFinanceViewBanner');if(!state.activeFinanceView){banner.hidden=true;banner.innerHTML='';return;}banner.hidden=false;banner.innerHTML=`<strong>★ Aktif görünüm: ${esc(state.activeFinanceView.name)}</strong><button type="button" data-clear-active-finance-view>Görünümü Kapat ×</button>`;}
function renderFinanceViews(){const list=$('#financeViewsList');list.innerHTML=state.financeSavedViews.length?state.financeSavedViews.map(view=>{const conditions=financeViewConditions(view),active=state.activeFinanceView?.id===view.id;return`<div class="field-row ${active?'view-row-active':''}"><span><strong>${esc(view.name)} ${view.is_default?'<small class="view-default">★ Varsayılan</small>':''}</strong><small>${conditions.length?conditions.map(esc).join(' · '):'Filtre yok'} · ${number((view.columns||[]).filter(item=>item.visible).length)} görünür sütun</small></span><span class="field-row-actions"><button type="button" data-apply-finance-view="${esc(view.id)}">Uygula</button><button type="button" data-update-finance-view="${esc(view.id)}">Güncelle</button><button type="button" data-default-finance-view="${esc(view.id)}">Varsayılan</button><button type="button" class="delete-field" data-delete-finance-view="${esc(view.id)}">Sil</button></span></div>`;}).join(''):'<div class="notice">Henüz kaydedilmiş finans görünümü yok.</div>';}
async function persistFinanceViews(message='Finans görünümleri kaydedildi.'){await api('/api/settings/finance-saved-views',{method:'PUT',body:{views:state.financeSavedViews}});renderFinanceViews();toast(message);}
async function openFinanceViews(){state.financeSavedViews=(await api('/api/settings/finance-saved-views')).data;renderCurrentFinanceViewSummary();renderFinanceViews();$('#financeViewsDialog').showModal();}
async function saveFinanceView(event){event.preventDefault();const name=event.currentTarget.elements.name.value.trim();if(!name)return;const view=currentFinanceViewSnapshot(name),conditions=financeViewConditions(view);if(!conditions.length&&!confirm('Bu görünümde filtre veya arama yok; yalnızca sütun düzeni kaydedilecek. Devam edilsin mi?'))return;const existing=state.financeSavedViews.find(item=>item.name.toLocaleLowerCase('tr-TR')===name.toLocaleLowerCase('tr-TR'));if(existing){view.id=existing.id;view.is_default=Boolean(existing.is_default);}state.financeSavedViews=[...state.financeSavedViews.filter(item=>item.id!==view.id&&item.name.toLocaleLowerCase('tr-TR')!==name.toLocaleLowerCase('tr-TR')),view];try{await persistFinanceViews('Finans görünümü ve içerdiği koşullar kaydedildi.');event.currentTarget.reset();renderCurrentFinanceViewSummary();}catch(error){toast(error.message,true);}}
async function applyFinanceView(id){const view=state.financeSavedViews.find(item=>item.id===id);if(!view)return;state.financeSelections=structuredClone(view.selections||{});state.financeRanges=structuredClone(view.ranges||{});state.financeTableColumns=mergeFinanceColumns(view.columns||[]);$('#financeSearch').value=view.search||'';state.activeFinanceView=view;$('#financeViewsDialog').close();renderFinanceFilters();updateActiveFinanceViewBanner();await loadFinance();toast(`${view.name} uygulandı: ${number(state.financeData?.total)} kurum grubu görüntüleniyor.`);}
async function updateFinanceView(id){const current=state.financeSavedViews.find(item=>item.id===id);if(!current)return;const replacement=currentFinanceViewSnapshot(current.name);replacement.id=id;replacement.is_default=Boolean(current.is_default);state.financeSavedViews=state.financeSavedViews.map(item=>item.id===id?replacement:item);try{await persistFinanceViews(`${current.name} güncel filtre ve sütunlarla yenilendi.`);}catch(error){toast(error.message,true);}}
async function setDefaultFinanceView(id){state.financeSavedViews=state.financeSavedViews.map(item=>({...item,is_default:item.id===id}));try{await persistFinanceViews('Varsayılan finans görünümü belirlendi.');}catch(error){toast(error.message,true);}}
async function deleteFinanceView(id){state.financeSavedViews=state.financeSavedViews.filter(item=>item.id!==id);if(state.activeFinanceView?.id===id)state.activeFinanceView=null;try{await persistFinanceViews('Finans görünümü silindi.');updateActiveFinanceViewBanner();}catch(error){toast(error.message,true);}}
function clearActiveFinanceView(){state.activeFinanceView=null;state.financeSelections={};state.financeRanges={};$('#financeSearch').value='';updateActiveFinanceViewBanner();renderFinanceFilters();loadFinance();}

function exportWithFilters(kind){const params=kind==='finance'?financeParams():institutionParams(),columns=kind==='finance'?state.financeTableColumns:state.tableColumns;params.set('columns',columns.filter(column=>column.visible).map(column=>column.key).join(','));window.location.href=`/api/${kind==='finance'?'finance/':''}export/xlsx?${params}`;}
async function previewImport(file){if(!file)return;state.importToken='';$('#commitImport').disabled=true;$('#importPreview').hidden=true;$('#importProgress').hidden=false;$('#importProgress').textContent=`${file.name} kontrol ediliyor…`;try{const buffer=await file.arrayBuffer(),result=await api('/api/import/preview',{method:'POST',body:buffer,headers:{'Content-Type':'application/octet-stream','X-File-Name':encodeURIComponent(file.name)}}),data=result.data;state.importToken=data.token;$('#importProgress').hidden=true;$('#importPreview').hidden=false;$('#importPreview').innerHTML=`<div class="preview-grid"><div><strong>${data.total}</strong><span>Toplam kayıt</span></div><div><strong>${data.new}</strong><span>Yeni</span></div><div><strong>${data.updated}</strong><span>Güncellenecek</span></div><div><strong>${data.panel_count}</strong><span>Panel</span></div></div>`;$('#commitImport').disabled=false;}catch(error){toast(error.message,true);}}
async function commitImport(){try{const result=await api('/api/import/commit',{method:'POST',body:{token:state.importToken}});$('#importDialog').close();toast(`${result.data.total} kayıt işlendi.`);await Promise.all([loadFilters(),loadAllInstitutions(),refreshInstitutions(),loadFinance()]);}catch(error){toast(error.message,true);}}
function renderCustomFieldList(){$('#customFieldList').innerHTML=state.customFields.filter(field=>field.entity_type==='institution').map(field=>`<div class="field-row" draggable="true" data-custom-field-id="${esc(field.id)}"><button type="button" class="drag-handle field-drag" title="Sürükleyerek taşı">⠿</button><span class="column-move"><button type="button" data-move-field="up">↑</button><button type="button" data-move-field="down">↓</button></span><button type="button" class="field-row-main" data-edit-custom-field="${esc(field.id)}"><strong>${esc(field.label)}</strong><small>${esc(field.field_key)} · ${esc(field.data_type)} · ${field.required?'Zorunlu':'İsteğe bağlı'}</small></button><span class="field-row-actions"><button type="button" data-edit-custom-field="${esc(field.id)}">Düzenle ✎</button><button type="button" class="delete-field" data-delete-custom-field="${esc(field.id)}">Sil 🗑</button></span></div>`).join('')||'<div class="notice">Henüz özel kurum alanı yok.</div>';}
async function openCustomFields(){renderCustomFieldList();$('#customFieldForm').hidden=true;$('#customFieldTrash').hidden=true;$('#customFieldDialog').showModal();await loadArchivedCustomFields();}
function editCustomField(field=null){const form=$('#customFieldForm');form.hidden=false;form.reset();const values=field||{entity_type:'institution'};for(const element of form.elements)if(element.name&&values[element.name]!==undefined){if(element.type==='checkbox')element.checked=Boolean(values[element.name]);else if(element.name==='options')element.value=(values.options||[]).join(', ');else element.value=values[element.name]??'';}form.scrollIntoView({behavior:'smooth',block:'nearest'});}
async function saveCustomField(event){event.preventDefault();if(!event.currentTarget.reportValidity())return;const data=formPayload(event.currentTarget),id=data.id;delete data.id;delete data.custom_values;data.options=data.options.split(',').map(value=>value.trim()).filter(Boolean);try{await api(id?`/api/custom-fields/${encodeURIComponent(id)}`:'/api/custom-fields',{method:id?'PUT':'POST',body:data});state.customFields=(await api('/api/custom-fields')).data;state.tableColumns=mergeColumns(state.tableColumns);renderCustomFieldList();event.currentTarget.hidden=true;toast('Kurum alanı kaydedildi; adı bütün ilgili ekranlarda güncellendi.');await loadFilters();}catch(error){toast(error.message,true);}}
async function archiveCustomField(id){if(!confirm('Alan silinen alanlara taşınacak; kayıtlı değerler korunacak. Devam edilsin mi?'))return;try{await api('/api/custom-fields/bulk-delete',{method:'POST',body:{field_ids:[id]}});state.customFields=(await api('/api/custom-fields')).data;state.tableColumns=mergeColumns(state.tableColumns);renderCustomFieldList();await Promise.all([loadArchivedCustomFields(),loadFilters()]);toast('Kurum alanı arşivlendi.');}catch(error){toast(error.message,true);}}
async function loadArchivedCustomFields(){state.archivedCustomFields=(await api('/api/custom-fields/trash?entity_type=institution')).data;$('#customFieldTrash').innerHTML=state.archivedCustomFields.length?`<strong>Silinen alanlar</strong>${state.archivedCustomFields.map(field=>`<div class="field-row"><span><strong>${esc(field.label)}</strong><small>${esc(field.field_key)} · ${esc(field.data_type)}</small></span><span class="field-row-actions"><button type="button" data-restore-custom-field="${esc(field.id)}">Geri Yükle</button><button type="button" class="delete-field" data-purge-custom-field="${esc(field.id)}">Kalıcı Sil</button></span></div>`).join('')}`:'<div class="notice success">Silinen kurum alanı yok.</div>';}
async function restoreCustomField(id){try{await api('/api/custom-fields/restore',{method:'POST',body:{field_ids:[id]}});state.customFields=(await api('/api/custom-fields')).data;renderCustomFieldList();await Promise.all([loadArchivedCustomFields(),loadFilters()]);toast('Kurum alanı geri yüklendi.');}catch(error){toast(error.message,true);}}
async function purgeCustomField(id){const field=state.archivedCustomFields.find(item=>item.id===id);if(!field)return;const confirmation=prompt(`${field.label} alanı ve bütün değerleri kalıcı silinecek. Devam etmek için KALICI SİL yazın.`);if(confirmation!=='KALICI SİL')return;try{await api('/api/custom-fields/purge',{method:'POST',body:{field_ids:[id],confirmation}});await loadArchivedCustomFields();toast('Kurum alanı kalıcı silindi.');}catch(error){toast(error.message,true);}}
async function saveCustomFieldOrder(){const ids=$$('[data-custom-field-id]',$('#customFieldList')).map(row=>row.dataset.customFieldId);try{state.customFields=(await api('/api/custom-fields/reorder',{method:'POST',body:{field_ids:ids}})).data;renderCustomFieldList();await loadFilters();toast('Kurum alanı sırası kaydedildi.');}catch(error){toast(error.message,true);}}
async function openBackups(){$('#backupDialog').showModal();const list=$('#backupList');try{const items=(await api('/api/backups')).data;list.innerHTML=items.length?items.map(item=>`<div class="backup-item"><div><strong>${esc(item.name)}</strong><span>${esc(item.modified)} · ${(item.size/1024).toFixed(1)} KB</span></div><a href="/api/backups/${encodeURIComponent(item.name)}">İndir</a></div>`).join(''):'<span class="subtext">Henüz yedek yok.</span>';}catch(error){toast(error.message,true);}}
async function createBackup(){try{await api('/api/backups',{method:'POST',body:{}});toast('Doğrulanmış yedek oluşturuldu.');await openBackups();}catch(error){toast(error.message,true);}}
function applyNavigation(){const nav=$('#mainNavigation'),byKey=new Map($$('[data-nav-key]',nav).map(node=>[node.dataset.navKey,node]));for(const item of state.navigationPreferences){const node=byKey.get(item.key);if(node){$('span',node).textContent=item.icon;$('b',node).textContent=item.label;node.hidden=!item.visible;nav.appendChild(node);}const title=$(`[data-page-title="${item.key}"]`),subtitle=$(`[data-page-subtitle="${item.key}"]`);if(title)title.textContent=item.title;if(subtitle)subtitle.textContent=item.subtitle;}const dynamic=$('#dynamicModuleNavigation'),studio=$('[data-view="platformStudio"]',nav),after=byKey.get('commissions');if(after&&dynamic){after.after(dynamic);dynamic.after(studio);}}
function renderNavigationSettings(){$('#navigationSettingsList').innerHTML=state.navigationDraft.map(item=>`<div class="navigation-setting-row" draggable="true" data-navigation-key="${esc(item.key)}"><span class="column-move"><button type="button" class="drag-handle">⠿</button><button type="button" data-config-move="up">↑</button><button type="button" data-config-move="down">↓</button></span><label>Simge<input data-nav-icon value="${esc(item.icon)}" maxlength="4"></label><label>Menü adı<input data-nav-label value="${esc(item.label)}"></label><label>Sayfa başlığı<input data-nav-title value="${esc(item.title)}"></label><label>Açıklama<input data-nav-subtitle value="${esc(item.subtitle)}"></label><label class="check-label"><input type="checkbox" data-nav-visible ${item.visible?'checked':''}> Göster</label></div>`).join('');}
function openNavigationSettings(){state.navigationDraft=structuredClone(state.navigationPreferences);renderNavigationSettings();$('#navigationDialog').showModal();}
function readNavigationSettings(){return $$('[data-navigation-key]',$('#navigationSettingsList')).map(row=>{const base=state.navigationDraft.find(item=>item.key===row.dataset.navigationKey);return{...base,icon:$('[data-nav-icon]',row).value.trim()||base.icon,label:$('[data-nav-label]',row).value.trim()||base.label,title:$('[data-nav-title]',row).value.trim()||base.title,subtitle:$('[data-nav-subtitle]',row).value.trim(),visible:$('[data-nav-visible]',row).checked};});}
async function saveNavigationSettings(){try{state.navigationPreferences=(await api('/api/settings/navigation',{method:'PUT',body:{navigation:readNavigationSettings()}})).data;applyNavigation();$('#navigationDialog').close();toast('Sayfa ve menü düzeni kaydedildi.');}catch(error){toast(error.message,true);}}
async function resetNavigationSettings(){if(!confirm('Sayfa ve menü adları varsayılana döndürülsün mü?'))return;try{state.navigationPreferences=(await api('/api/settings/navigation',{method:'PUT',body:{navigation:[]}})).data;state.navigationDraft=structuredClone(state.navigationPreferences);renderNavigationSettings();applyNavigation();toast('Sayfa ve menü düzeni varsayılana döndü.');}catch(error){toast(error.message,true);}}

function applyTheme(theme=state.themePreferences){const value={...DEFAULT_THEME,...theme},root=document.documentElement,density={compact:9,normal:13,comfortable:17}[value.density]||13;root.style.setProperty('--bg',value.background);root.style.setProperty('--surface',value.surface);root.style.setProperty('--text',value.text);root.style.setProperty('--muted',value.muted);root.style.setProperty('--green',value.primary);root.style.setProperty('--green-dark',value.primary_dark);root.style.setProperty('--red',value.danger);root.style.setProperty('--sidebar-bg',value.sidebar);root.style.setProperty('--font-scale',Number(value.font_scale)/100);root.style.setProperty('--radius',`${value.radius}px`);root.style.setProperty('--sidebar-width',`${value.sidebar_width}px`);root.style.setProperty('--row-padding',`${density}px`);}
function themeFormValue(){const form=$('#themeForm'),value={};for(const element of form.elements)if(element.name)value[element.name]=['font_scale','radius','sidebar_width'].includes(element.name)?Number(element.value):element.value;return value;}
function fillThemeForm(theme){const form=$('#themeForm'),value={...DEFAULT_THEME,...theme};for(const element of form.elements)if(element.name&&value[element.name]!==undefined)element.value=value[element.name];}
function openThemeSettings(){fillThemeForm(state.themePreferences);applyTheme(state.themePreferences);$('#themeDialog').showModal();}
async function saveThemeSettings(event){event.preventDefault();try{state.themePreferences=(await api('/api/settings/theme',{method:'PUT',body:{theme:themeFormValue()}})).data;applyTheme();$('#themeDialog').close();toast('Tema kaydedildi.');}catch(error){toast(error.message,true);}}
function resetThemePreview(){fillThemeForm(DEFAULT_THEME);applyTheme(DEFAULT_THEME);toast('Varsayılan tema ön izleniyor; kalıcı olması için Temayı Kaydet düğmesine basın.');}

const historyLabels={institution_form_fields:'Kurum formu',dynamic_filters:'Kurum filtreleri',table_columns:'Kurum sütunları',finance_filters:'Finans filtreleri',finance_table_columns:'Finans sütunları',finance_summary_cards:'Finans kartları',finance_saved_views:'Finans görünümleri',navigation_preferences:'Sayfa ve menü',theme_preferences:'Tema'};
async function loadSettingsHistory(){const key=$('#settingsHistoryKey').value,list=$('#settingsHistoryList');list.innerHTML='<div class="notice">Geçmiş yükleniyor…</div>';try{const items=(await api(`/api/settings/history?key=${encodeURIComponent(key)}`)).data;list.innerHTML=items.length?items.map(item=>`<div class="history-row"><div><strong>${esc(historyLabels[key]||key)}</strong><span>${esc(item.changed_at)} · Önceki kayıtlı sürüm</span></div><button class="button secondary compact" type="button" data-restore-setting-history="${item.id}">Bu Sürüme Dön</button></div>`).join(''):'<div class="notice">Bu ayar için önceki sürüm yok.</div>';}catch(error){toast(error.message,true);}}
async function openSettingsHistory(){$('#settingsHistoryDialog').showModal();await loadSettingsHistory();}
async function restoreSettingHistory(id){if(!confirm('Seçilen ayar sürümü geri yüklensin mi? Mevcut hâl ayrıca geçmişe kaydedilecektir.'))return;try{await api('/api/settings/history/restore',{method:'POST',body:{history_id:Number(id)}});toast('Ayar sürümü geri yüklendi; ekran yenileniyor.');setTimeout(()=>window.location.reload(),600);}catch(error){toast(error.message,true);}}

function platformModule(id){return state.dynamicModules.find(item=>item.id===id||item.module_key===id);}
function renderDynamicNavigation(){const wrap=$('#dynamicModuleNavigation');wrap.innerHTML=state.dynamicModules.filter(item=>item.active&&item.menu_visible).map(item=>`<button class="nav-item" data-dynamic-module="${esc(item.id)}" style="--module-color:${esc(item.color)}"><span>${esc(item.icon)}</span><b>${esc(item.label)}</b></button>`).join('');}
async function loadPlatformBootstrap(){const result=await api('/api/platform/bootstrap');state.platformBootstrap=result.data;state.dynamicModules=result.data.modules||[];renderDynamicNavigation();if(state.studioModule){state.studioModule=platformModule(state.studioModule.id)||null;}renderPlatformStudio();}
function dynamicFieldType(field){return({text:'Metin',longtext:'Uzun metin',number:'Sayı',money:'Para',date:'Tarih',boolean:'Evet/Hayır',select:'Seçim',multiselect:'Çoklu seçim',relation:'İlişki',formula:'ƒx Formül'})[field.data_type]||field.data_type;}
function platformValue(field,value){if(value===null||value===undefined||value==='')return'—';if(field.data_type==='money')return new Intl.NumberFormat('tr-TR',{style:'currency',currency:'TRY'}).format(decimal(value));if(['number','formula'].includes(field.data_type)){const places=Number(field.decimal_places||0);return Number(decimal(value)).toLocaleString('tr-TR',{minimumFractionDigits:places,maximumFractionDigits:places});}if(field.data_type==='boolean')return value===true||value==='true'||value==='1'?'Evet':'Hayır';if(Array.isArray(value))return value.join(', ');return String(value);}
function dynamicActions(placement){return(state.currentDynamicModule?.actions||[]).filter(item=>item.active&&item.placement===placement).sort((a,b)=>Number(a.sort_order||0)-Number(b.sort_order||0));}
function actionNeedsRecord(action){return['edit_record','archive_record','duplicate_record'].includes(action.action_type);}
function actionClass(action,row=false){const style=action.style||'secondary';return row?`button compact ${style}`:`button ${style}`;}
function configuredActionButton(action,{recordId='',placement=action.placement}={}){let disabled=false;if(placement==='page_top'&&actionNeedsRecord(action)){const count=state.dynamicSelectedRecords.size;disabled=action.action_type==='archive_record'?count<1:count!==1;}return`<button type="button" class="${esc(actionClass(action,placement==='row'))}" data-configured-action="${esc(action.id)}" ${recordId?`data-record-id="${esc(recordId)}"`:''} ${disabled?'disabled':''}>${action.icon?`${esc(action.icon)} `:''}${esc(action.label)}</button>`;}
function renderDynamicActionAreas(){const page=$('#dynamicPageActions');if(page)page.innerHTML=dynamicActions('page_top').map(action=>configuredActionButton(action,{placement:'page_top'})).join('');const header=$('#dynamicFormHeaderActions'),footer=$('#dynamicFormFooterActions');if(header)header.innerHTML=dynamicActions('form_header').map(action=>configuredActionButton(action,{placement:'form_header'})).join('');if(footer)footer.innerHTML=dynamicActions('form_footer').map(action=>configuredActionButton(action,{placement:'form_footer'})).join('');}
async function duplicateDynamicRecord(id){try{const item=(await api(`/api/platform/modules/${encodeURIComponent(state.currentDynamicModule.id)}/records/${encodeURIComponent(id)}`)).data;const copy={values:structuredClone(item.values||{})};await openDynamicRecord(copy);}catch(error){toast(error.message,true);}}
async function archiveDynamicRecord(id){return archiveDynamicRecords([id]);}
async function handleDynamicConfiguredAction(actionId,recordId=''){const action=(state.currentDynamicModule?.actions||[]).find(item=>item.id===actionId&&item.active);if(!action)return;const selected=[...state.dynamicSelectedRecords];const target=recordId||(selected.length===1?selected[0]:'');if(action.action_type==='new_record')return openDynamicRecord();if(action.action_type==='export_xlsx')return exportDynamicModule();if(action.action_type==='edit_record'){if(!target)return toast('Düzenlemek için bir kayıt seçin.',true);return editDynamicRecord(target);}if(action.action_type==='duplicate_record'){if(!target)return toast('Kopyalamak için bir kayıt seçin.',true);return duplicateDynamicRecord(target);}if(action.action_type==='archive_record'){const ids=recordId?[recordId]:selected;return archiveDynamicRecords(ids,action.confirmation_text);}if(action.action_type==='save_record'){const form=$('#dynamicRecordForm');if(form)form.requestSubmit();return;}if(action.action_type==='cancel_form'){const dialog=$('#dynamicRecordDialog');if(dialog?.open)dialog.close();}}
async function activateDynamicModule(id){const module=platformModule(id);if(!module)return;state.currentDynamicModule=module;state.dynamicSelections={};state.dynamicRanges={};state.dynamicSelectedRecords.clear();$('#dynamicModuleSearch').value='';await showView('dynamicModule');$$('[data-dynamic-module]').forEach(button=>button.classList.toggle('active',button.dataset.dynamicModule===module.id));}
function dynamicParams(){const params=new URLSearchParams(),query=$('#dynamicModuleSearch').value.trim();if(query)params.set('query',query);for(const[key,value]of Object.entries(state.dynamicSelections))if(value)params.append(key,value);for(const[key,range]of Object.entries(state.dynamicRanges)){const field=state.currentDynamicModule?.fields.find(item=>item.field_key===key),date=field?.data_type==='date';if(range.min)params.set(`${date?'from':'min'}.${key}`,range.min);if(range.max)params.set(`${date?'to':'max'}.${key}`,range.max);}return params;}
async function loadDynamicModule(){const module=state.currentDynamicModule;if(!module)return;const params=dynamicParams();state.dynamicData=(await api(`/api/platform/modules/${encodeURIComponent(module.id)}/records${params.toString()?`?${params}`:''}`)).data;state.dynamicViews=(await api(`/api/platform/modules/${encodeURIComponent(module.id)}/views`)).data;renderDynamicModule();}
function renderDynamicModule(){const data=state.dynamicData,module=state.currentDynamicModule;if(!data||!module)return;document.documentElement.style.setProperty('--module-color',module.color);$('#dynamicModuleTitle').textContent=module.label;$('#dynamicModuleSubtitle').textContent=module.description||`${module.singular_label} kayıtlarını yönetin.`;$('#dynamicResultCount').textContent=`${number(data.total)} kayıt`;$('#dynamicModuleEmpty').hidden=Boolean(data.items.length);const aggregates=Object.values(data.aggregates||{});renderDynamicActionAreas();const topRecordActions=dynamicActions('page_top').filter(actionNeedsRecord),showSelection=topRecordActions.length>0;$('#dynamicModuleKpis').innerHTML=`<article class="kpi"><span>Toplam Kayıt</span><strong>${number(data.total)}</strong><small>Filtrelenmiş sonuç</small></article>`+aggregates.slice(0,5).map(item=>`<article class="kpi ${Number(item.value)<0?'danger':''}"><span>${esc(item.label)}</span><strong>${esc(item.data_type==='money'?new Intl.NumberFormat('tr-TR',{style:'currency',currency:'TRY'}).format(decimal(item.value)):Number(decimal(item.value)).toLocaleString('tr-TR'))}</strong><small>${esc(({sum:'Toplam',avg:'Ortalama',min:'En düşük',max:'En yüksek',count:'Dolu kayıt'})[item.operation]||item.operation)}</small></article>`).join('');const filterFields=data.fields.filter(field=>field.filterable&&data.filter_options[field.field_key]),rangeFields=data.fields.filter(field=>field.filterable&&['number','money','formula','date'].includes(field.data_type));$('#dynamicModuleFilters').innerHTML=filterFields.map(field=>`<label>${esc(field.label)}<select data-dynamic-filter="${esc(field.field_key)}"><option value="">Tümü</option>${(data.filter_options[field.field_key]||[]).map(option=>`<option value="${esc(option.value)}" ${state.dynamicSelections[field.field_key]===option.value?'selected':''}>${esc(option.label)} (${number(option.count)})</option>`).join('')}</select></label>`).join('')+rangeFields.map(field=>{const range=state.dynamicRanges[field.field_key]||{},type=field.data_type==='date'?'date':'number';return`<label>${esc(field.label)} aralığı<span class="dynamic-range-pair"><input type="${type}" step="any" data-dynamic-range="${esc(field.field_key)}" data-range-edge="min" value="${esc(range.min||'')}" placeholder="En az"><input type="${type}" step="any" data-dynamic-range="${esc(field.field_key)}" data-range-edge="max" value="${esc(range.max||'')}" placeholder="En çok"></span></label>`;}).join('');const fields=data.fields.filter(field=>field.visible),rowActions=dynamicActions('row');$('#dynamicModuleColgroup').innerHTML=(showSelection?'<col style="width:46px">':'')+fields.map(field=>`<col style="width:${field.width}px">`).join('')+(rowActions.length?'<col style="width:220px">':'');$('#dynamicModuleHead').innerHTML=(showSelection?`<th><input type="checkbox" data-dynamic-select-all ${data.items.length&&data.items.every(item=>state.dynamicSelectedRecords.has(item.id))?'checked':''}></th>`:'')+fields.map(field=>`<th>${field.data_type==='formula'?'ƒx ':''}${esc(field.label)}</th>`).join('')+(rowActions.length?'<th>İşlemler</th>':'');$('#dynamicModuleBody').innerHTML=data.items.map(item=>`<tr>${showSelection?`<td><input type="checkbox" data-dynamic-select-record="${esc(item.id)}" ${state.dynamicSelectedRecords.has(item.id)?'checked':''}></td>`:''}${fields.map(field=>`<td class="${field.data_type==='formula'?'dynamic-formula-value':''}">${esc(platformValue(field,(item.display_values||item.values)[field.field_key]))}</td>`).join('')}${rowActions.length?`<td><div class="row-action-set">${rowActions.map(action=>configuredActionButton(action,{recordId:item.id,placement:'row'})).join('')}</div></td>`:''}</tr>`).join('');$('#dynamicModuleFoot').innerHTML=aggregates.length?`<tr>${showSelection?'<td></td>':''}${fields.map((field,index)=>{const item=data.aggregates[field.field_key];return`<td>${item?esc(platformValue(field,item.value)):index===0?'GENEL TOPLAM':''}</td>`;}).join('')}${rowActions.length?'<td></td>':''}</tr>`:'';$('#dynamicSavedViews').innerHTML='<option value="">Kayıtlı görünüm seçin</option>'+state.dynamicViews.map(view=>`<option value="${esc(view.id)}">${view.is_default?'★ ':''}${esc(view.name)}</option>`).join('');requestAnimationFrame(refreshTopScrollbars);}
async function relationChoices(field){if(field.relation_target==='institutions')return(state.platformBootstrap.relations?.institutions||[]).map(item=>({value:item.id,label:`${item.name}${item.city?` · ${item.city}`:''}`}));const target=platformModule(field.relation_target);if(!target)return[];const data=(await api(`/api/platform/modules/${encodeURIComponent(target.id)}/records`)).data;return data.items.map(item=>({value:item.id,label:item.title}));}
async function dynamicRecordControl(field,value){const label=`${esc(field.label)}${field.required?' <b>*</b>':''}`;if(field.data_type==='formula')return`<label><span>ƒx ${label}</span><input value="${esc(platformValue(field,value))}" disabled><small class="field-help">Otomatik hesaplanır</small></label>`;if(field.data_type==='longtext')return`<label class="wide">${label}<textarea data-dynamic-field="${esc(field.field_key)}" rows="3" ${field.required?'required':''}>${esc(value||'')}</textarea></label>`;if(field.data_type==='boolean')return`<label class="check-label"><input type="checkbox" data-dynamic-field="${esc(field.field_key)}" ${value?'checked':''}> ${label}</label>`;if(field.data_type==='select'||field.data_type==='multiselect'){const values=Array.isArray(value)?value:[value];return`<label>${label}<select data-dynamic-field="${esc(field.field_key)}" ${field.data_type==='multiselect'?'multiple size="5"':''} ${field.required?'required':''}><option value=""></option>${field.options.map(option=>`<option ${values.includes(option)?'selected':''}>${esc(option)}</option>`).join('')}</select></label>`;}if(field.data_type==='relation'){const choices=await relationChoices(field);return`<label>${label}<select data-dynamic-field="${esc(field.field_key)}" ${field.required?'required':''}><option value="">Seçin…</option>${choices.map(option=>`<option value="${esc(option.value)}" ${String(value||'')===String(option.value)?'selected':''}>${esc(option.label)}</option>`).join('')}</select></label>`;}const type=field.data_type==='date'?'date':field.data_type==='number'||field.data_type==='money'?'number':'text',step=field.data_type==='number'||field.data_type==='money'?'step="any"':'';return`<label>${label}<input type="${type}" ${step} data-dynamic-field="${esc(field.field_key)}" value="${esc(value||'')}" placeholder="${esc(field.placeholder||'')}" ${field.required?'required':''}></label>`;}
async function openDynamicRecord(record=null){const module=state.currentDynamicModule;if(!module)return;const values=record?.values||{};$('#dynamicRecordDialogTitle').textContent=record?.id?`${module.singular_label} düzenle`:`Yeni ${module.singular_label}`;const form=$('#dynamicRecordForm');form.reset();form.elements.id.value=record?.id||'';form.elements.row_version.value=record?.row_version||'';$('#dynamicRecordGrid').innerHTML=(await Promise.all(module.fields.filter(field=>field.active).map(field=>dynamicRecordControl(field,values[field.field_key])))).join('');renderDynamicActionAreas();$('#dynamicRecordDialog').showModal();}
async function saveDynamicRecord(event){event.preventDefault();const form=event.currentTarget;if(!form.reportValidity())return;const values={};$$('[data-dynamic-field]',form).forEach(input=>{if(input.type==='checkbox')values[input.dataset.dynamicField]=input.checked;else if(input.multiple)values[input.dataset.dynamicField]=[...input.selectedOptions].map(option=>option.value).filter(Boolean);else values[input.dataset.dynamicField]=input.value;});const id=form.elements.id.value,payload={values,row_version:form.elements.row_version.value};try{const result=await api(`/api/platform/modules/${encodeURIComponent(state.currentDynamicModule.id)}/records${id?`/${encodeURIComponent(id)}`:''}`,{method:id?'PUT':'POST',body:payload});form.closest('dialog').close();await loadDynamicModule();const rules=result.data.applied_rules||[];toast(rules.length?`Kayıt kaydedildi; ${rules.join(', ')} kuralı uygulandı.`:'Kayıt kaydedildi; formüller yenilendi.');}catch(error){toast(error.message,true);}}
async function editDynamicRecord(id){try{const item=(await api(`/api/platform/modules/${encodeURIComponent(state.currentDynamicModule.id)}/records/${encodeURIComponent(id)}`)).data;await openDynamicRecord(item);}catch(error){toast(error.message,true);}}
async function archiveDynamicRecord(id){if(!confirm('Kayıt arşive alınsın mı?'))return;try{await api(`/api/platform/modules/${encodeURIComponent(state.currentDynamicModule.id)}/records/${encodeURIComponent(id)}`,{method:'DELETE'});await loadDynamicModule();toast('Kayıt arşive alındı.');}catch(error){toast(error.message,true);}}
async function saveCurrentDynamicView(){const name=prompt('Görünüm adı:');if(!name)return;try{await api(`/api/platform/modules/${encodeURIComponent(state.currentDynamicModule.id)}/views`,{method:'POST',body:{name,filters:{query:$('#dynamicModuleSearch').value.trim(),selections:state.dynamicSelections,ranges:state.dynamicRanges},columns:state.currentDynamicModule.fields.filter(field=>field.visible).map(field=>field.field_key)}});await loadDynamicModule();toast('Görünüm kaydedildi.');}catch(error){toast(error.message,true);}}
async function applyDynamicView(id){const view=state.dynamicViews.find(item=>item.id===id);if(!view)return;$('#dynamicModuleSearch').value=view.filters?.query||'';state.dynamicSelections=structuredClone(view.filters?.selections||{});state.dynamicRanges=structuredClone(view.filters?.ranges||{});await loadDynamicModule();toast(`${view.name} görünümü uygulandı.`);}
function exportDynamicModule(){if(!state.currentDynamicModule)return;const params=dynamicParams();params.set('columns',state.currentDynamicModule.fields.filter(field=>field.visible).map(field=>field.field_key).join(','));window.location.href=`/api/platform/modules/${encodeURIComponent(state.currentDynamicModule.id)}/export/xlsx?${params}`;}

function renderPlatformStudio(){if(!$('#studioModuleList'))return;$('#coreModuleCards').innerHTML=(state.platformBootstrap.core_modules||[]).map(item=>`<button class="core-module-card" data-core-module="${esc(item.key)}"><b>${esc(item.icon)} ${esc(item.label)}</b><small>Korunan ana bölüm</small></button>`).join('');const active=state.dynamicModules.map(item=>`<button class="studio-module-card ${state.studioModule?.id===item.id?'active':''}" draggable="true" data-studio-module="${esc(item.id)}" style="--module-color:${esc(item.color)}"><i>${esc(item.icon)}</i><span><b>${esc(item.label)}</b><small>${number(item.fields.length)} alan · ${number(item.record_count)} kayıt</small></span><em>›</em></button>`).join(''),archived=state.platformBootstrap.archived_modules||[];$('#studioModuleList').innerHTML=active+(archived.length?`<details class="field-trash"><summary>Arşivlenen bölümler (${number(archived.length)})</summary>${archived.map(item=>`<div class="field-row"><span><strong>${esc(item.icon)} ${esc(item.label)}</strong><small>${number(item.record_count)} kayıt korunuyor</small></span><span class="field-row-actions"><button type="button" data-restore-studio-module="${esc(item.id)}">Geri Yükle</button><button type="button" class="permanent-delete" data-purge-studio-module="${esc(item.id)}">Kalıcı Sil</button></span></div>`).join('')}</details>`:'');if(!state.studioModule){$('#studioEmpty').hidden=false;$('#studioModuleWorkspace').hidden=true;return;}const module=state.studioModule;$('#studioEmpty').hidden=true;$('#studioModuleWorkspace').hidden=false;$('#studioModuleIcon').textContent=module.icon;$('#studioModuleIcon').style.background=module.color;$('#studioModuleName').textContent=module.label;$('#studioModuleDescription').textContent=module.description||'Açıklama yok';renderStudioFields();renderStudioActions();renderStudioRules();}
function renderStudioFields(){const module=state.studioModule;if(!module)return;const active=module.fields.map(field=>`<div class="field-row ${field.data_type==='formula'?'formula-field':field.data_type==='relation'?'relation-field':''}" draggable="true" data-dynamic-field-id="${esc(field.id)}"><span class="move-stack"><button type="button" data-studio-field-move="up">↑</button><button type="button" data-studio-field-move="down">↓</button></span><button class="field-row-main" type="button" data-edit-dynamic-field="${esc(field.id)}"><strong>${field.data_type==='formula'?'ƒx ':''}${esc(field.label)} <small class="field-type-pill">${esc(dynamicFieldType(field))}</small></strong><small>${esc(field.field_key)} · ${field.required?'Zorunlu':'İsteğe bağlı'} · ${field.aggregate_type!=='none'?`Özet: ${field.aggregate_type}`:'Özet yok'}${field.formula?` · ${esc(field.formula)}`:''}</small></button><span class="field-row-actions"><button type="button" data-edit-dynamic-field="${esc(field.id)}">Düzenle</button><button type="button" class="delete-field" data-archive-dynamic-field="${esc(field.id)}">Arşivle</button></span></div>`).join('')||'<div class="notice">Bu bölümde alan yok. İlk alanı ekleyin.</div>',archived=module.archived_fields||[];$('#studioFieldList').innerHTML=active+(archived.length?`<details class="field-trash"><summary>Arşivlenen alanlar (${number(archived.length)})</summary>${archived.map(field=>`<div class="field-row"><span><strong>${esc(field.label)}</strong><small>${esc(field.field_key)} · Değerler korunuyor</small></span><span class="field-row-actions"><button type="button" data-restore-dynamic-field="${esc(field.id)}">Geri Yükle</button></span></div>`).join('')}</details>`:'');}
function dynamicActionTypeLabel(type){return({new_record:'Yeni kayıt',edit_record:'Düzenle',save_record:'Kaydet',archive_record:'Sil / arşivle',duplicate_record:'Kopyala',export_xlsx:'Excel indir',cancel_form:'Vazgeç'})[type]||type;}
function dynamicActionPlacementLabel(value){return({page_top:'Sayfa üstü',row:'Kayıt satırı',form_header:'Form üstü',form_footer:'Form altı'})[value]||value;}
function renderStudioActions(){const module=state.studioModule;if(!module)return;const active=module.actions?.length?module.actions.map(action=>`<div class="field-row" draggable="true" data-dynamic-action-id="${esc(action.id)}"><span class="move-stack"><button type="button" data-studio-action-move="up">↑</button><button type="button" data-studio-action-move="down">↓</button></span><button class="field-row-main" type="button" data-edit-dynamic-action="${esc(action.id)}"><strong>${action.icon?`${esc(action.icon)} `:''}${esc(action.label)} <small class="field-type-pill">${esc(dynamicActionTypeLabel(action.action_type))}</small></strong><small>${esc(dynamicActionPlacementLabel(action.placement))} · ${esc(action.style)}${action.confirmation_text?' · Onay sorar':''}</small></button><span class="field-row-actions"><button type="button" data-edit-dynamic-action="${esc(action.id)}">Düzenle</button><button type="button" class="delete-field" data-archive-dynamic-action="${esc(action.id)}">Arşivle</button></span></div>`).join(''):'<div class="notice">Bu bölümde aktif eylem yok.</div>',archived=module.archived_actions||[];$('#studioActionList').innerHTML=active+(archived.length?`<details class="field-trash"><summary>Arşivlenen eylemler (${number(archived.length)})</summary>${archived.map(action=>`<div class="field-row"><span><strong>${esc(action.label)}</strong><small>${esc(dynamicActionTypeLabel(action.action_type))} · ${esc(dynamicActionPlacementLabel(action.placement))}</small></span><span class="field-row-actions"><button type="button" data-restore-dynamic-action="${esc(action.id)}">Geri Yükle</button></span></div>`).join('')}</details>`:'');}
function renderStudioRules(){const module=state.studioModule;if(!module)return;const active=module.rules.length?module.rules.map(rule=>`<article class="rule-card platform-rule"><div><strong>${esc(rule.name)}</strong><span>${number(rule.conditions.length)} koşul · ${number(rule.actions.length)} işlem</span></div><div class="rule-actions"><button type="button" data-edit-dynamic-rule="${esc(rule.id)}">Düzenle</button><button type="button" data-archive-dynamic-rule="${esc(rule.id)}">Arşivle</button></div></article>`).join(''):'<div class="notice">Henüz iş kuralı yok. “Bu olursa şunu yap” kuralı ekleyebilirsiniz.</div>',archived=module.archived_rules||[];$('#studioRuleList').innerHTML=active+(archived.length?`<details class="field-trash"><summary>Arşivlenen kurallar (${number(archived.length)})</summary>${archived.map(rule=>`<div class="field-row"><strong>${esc(rule.name)}</strong><span class="field-row-actions"><button type="button" data-restore-dynamic-rule="${esc(rule.id)}">Geri Yükle</button></span></div>`).join('')}</details>`:'');}
async function selectStudioModule(id){state.studioModule=platformModule(id)||null;renderPlatformStudio();await loadPlatformHistory();}
function openDynamicModuleEditor(module=null){const form=$('#dynamicModuleForm');form.reset();const values=module||{color:'#15865d',icon:'▦',menu_visible:true,active:true};for(const input of form.elements)if(input.name&&values[input.name]!==undefined){if(input.type==='checkbox')input.checked=Boolean(values[input.name]);else input.value=values[input.name]??'';}$('#dynamicModuleDialog').showModal();}
function relationTargetOptions(selected=''){return[{value:'institutions',label:'Kurumlar'},...state.dynamicModules.map(item=>({value:item.id,label:item.label}))].map(item=>`<option value="${esc(item.value)}" ${item.value===selected?'selected':''}>${esc(item.label)}</option>`).join('');}
function openDynamicFieldEditor(field=null){const module=state.studioModule;if(!module)return;const form=$('#dynamicFieldForm');form.reset();const values=field||{module_id:module.id,data_type:'text',aggregate_type:'none',decimal_places:2,width:160,visible:true,filterable:true,active:true};$('#dynamicRelationTarget').innerHTML='<option value="">Hedef seçin…</option>'+relationTargetOptions(values.relation_target||'');for(const input of form.elements)if(input.name&&values[input.name]!==undefined){if(input.type==='checkbox')input.checked=Boolean(values[input.name]);else if(input.name==='options')input.value=(values.options||[]).join(', ');else input.value=values[input.name]??'';}$('#dynamicFormulaBuilder').innerHTML=`<select id="dynamicFormulaFieldPicker"><option value="">Formüle alan ekle…</option>${module.fields.map(item=>`<option value="${esc(item.field_key)}">${esc(item.label)} · ${esc(item.field_key)}</option>`).join('')}</select>${[' + ',' - ',' * ',' / ','(',')','EGER(, , )','YUVARLA(, 2)'].map(token=>`<button type="button" data-dynamic-formula-token="${esc(token)}">${esc(token.trim())}</button>`).join('')}`;$('#dynamicFieldDialog').showModal();}
function dynamicRuleFieldOptions(selected='',editableOnly=false){return(state.studioModule?.fields||[]).filter(field=>!editableOnly||field.data_type!=='formula').map(field=>`<option value="${esc(field.field_key)}" ${field.field_key===selected?'selected':''}>${esc(field.label)}</option>`).join('');}
function addDynamicConditionRow(item={field:'',operator:'eq',value:''}){$('#dynamicRuleConditions').insertAdjacentHTML('beforeend',`<div class="condition-row platform-condition"><select data-rule-condition-field><option value="">Alan seçin…</option>${dynamicRuleFieldOptions(item.field)}</select><select data-rule-condition-operator>${[{v:'eq',l:'Eşittir'},{v:'ne',l:'Eşit değildir'},{v:'contains',l:'İçerir'},{v:'gt',l:'Büyüktür'},{v:'gte',l:'Büyük/eşit'},{v:'lt',l:'Küçüktür'},{v:'lte',l:'Küçük/eşit'},{v:'empty',l:'Boş'},{v:'not_empty',l:'Boş değil'}].map(option=>`<option value="${option.v}" ${option.v===item.operator?'selected':''}>${option.l}</option>`).join('')}</select><input data-rule-condition-value value="${esc(item.value||'')}" placeholder="Değer"><button type="button" data-remove-dynamic-rule-row>×</button></div>`);}
function addDynamicActionRow(item={type:'set',field:'',value:''}){$('#dynamicRuleActions').insertAdjacentHTML('beforeend',`<div class="condition-row platform-action"><select data-rule-action-type><option value="set" ${item.type==='set'?'selected':''}>Değer ata</option><option value="copy" ${item.type==='copy'?'selected':''}>Başka alandan kopyala</option><option value="formula" ${item.type==='formula'?'selected':''}>Formülle hesapla</option></select><select data-rule-action-field><option value="">Hedef alan…</option>${dynamicRuleFieldOptions(item.field,true)}</select><input data-rule-action-value value="${esc(item.value||'')}" placeholder="Değer, alan anahtarı veya formül"><button type="button" data-remove-dynamic-rule-row>×</button></div>`);}
function actionAllowedPlacements(type){return({new_record:['page_top'],export_xlsx:['page_top'],edit_record:['page_top','row'],archive_record:['page_top','row'],duplicate_record:['page_top','row'],save_record:['form_header','form_footer'],cancel_form:['form_header','form_footer']})[type]||[];}
function updateDynamicActionPlacementOptions(){const form=$('#dynamicActionForm'),type=form.elements.action_type.value,current=form.elements.placement.value,labels={page_top:'Sayfa üstü',row:'Kayıt satırı',form_header:'Form üstü',form_footer:'Form altı'},allowed=actionAllowedPlacements(type);form.elements.placement.innerHTML=allowed.map(value=>`<option value="${value}">${labels[value]}</option>`).join('');form.elements.placement.value=allowed.includes(current)?current:allowed[0]||'';}
function openDynamicActionEditor(action=null){const module=state.studioModule;if(!module)return;const form=$('#dynamicActionForm');form.reset();const values=action||{module_id:module.id,action_type:'new_record',placement:'page_top',style:'secondary',active:true};for(const input of form.elements)if(input.name&&values[input.name]!==undefined){if(input.type==='checkbox')input.checked=Boolean(values[input.name]);else input.value=values[input.name]??'';}updateDynamicActionPlacementOptions();if(action)form.elements.placement.value=action.placement;$('#dynamicActionDialog').showModal();}
