function moveStudioAction(event){const button=event.target.closest('[data-studio-action-move]');if(!button)return;const row=button.closest('[data-dynamic-action-id]');if(button.dataset.studioActionMove==='up'&&row.previousElementSibling)row.parentNode.insertBefore(row,row.previousElementSibling);if(button.dataset.studioActionMove==='down'&&row.nextElementSibling)row.parentNode.insertBefore(row.nextElementSibling,row);}
async function openAssistantSettings(){try{const result=(await api('/api/assistant/settings')).data;const form=$('#assistantSettingsForm');form.elements.model.value=result.model||'gpt-5.6';form.elements.api_key.value='';form.elements.clear_key.checked=false;const storage=result.storage_secure?'Windows DPAPI ile şifreli':'Geliştirme sistemi dosya koruması';$('#assistantSettingsStatus').innerHTML=`<strong>${result.configured?'OpenAI Vision yapılandırıldı':'OpenAI Vision henüz yapılandırılmadı'}</strong><br>${esc(result.key_hint||'Anahtar yok')} · ${esc(storage)}`;$('#assistantSettingsDialog').showModal();}catch(error){toast(error.message,true);}}
async function saveAssistantSettings(event){event.preventDefault();const form=event.currentTarget;if(!form.reportValidity())return;try{const payload={model:form.elements.model.value,clear_key:form.elements.clear_key.checked};if(form.elements.api_key.value.trim())payload.api_key=form.elements.api_key.value.trim();const result=(await api('/api/assistant/settings',{method:'POST',body:payload})).data;state.assistantStatus=result;renderAssistantMode();$('#assistantSettingsDialog').close();toast(result.configured?'LOGOS Asistan Vision güvenli biçimde yapılandırıldı.':'Asistan yerel güvenli moda alındı.');}catch(error){toast(error.message,true);}}
function renderAssistantReply(result){const reply=$('#logosAssistantReply');reply.hidden=false;reply.innerHTML=`<strong>${esc(result.assistant_text||result.summary||'')}</strong>${result.summary&&result.assistant_text&&result.summary!==result.assistant_text?`<span>${esc(result.summary)}</span>`:''}${(result.warnings||[]).map(item=>`<span>${esc(item)}</span>`).join('')}${(result.suggestions||[]).length?`<div class="assistant-suggestions">${result.suggestions.map(item=>`<button type="button" data-assistant-suggestion="${esc(item)}">${esc(item)}</button>`).join('')}</div>`:''}`;}
function renderAssistantMode(){const node=$('#logosAssistantMode');if(!node)return;const status=state.assistantStatus||{};node.className=`assistant-mode ${status.configured?'online':'local'}`;node.textContent=status.configured?`OpenAI Vision bağlı · ${status.model||''}`:'Yerel güvenli asistan · OpenAI Vision bağlı değil';}
function clearAssistantImage(){state.assistantImageData='';const input=$('#logosAssistantImage');if(input)input.value='';const preview=$('#logosAssistantImagePreview');if(preview)preview.innerHTML='<span>Görsel eklenmedi</span>';}
async function setAssistantImage(file){if(!file){clearAssistantImage();return;}if(!['image/png','image/jpeg','image/webp'].includes(file.type)){toast('Asistan görseli PNG, JPG veya WEBP olmalıdır.',true);clearAssistantImage();return;}if(file.size>7*1024*1024){toast('Asistan görseli 7 MB sınırını aşıyor.',true);clearAssistantImage();return;}const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result||''));reader.onerror=()=>reject(new Error('Görsel okunamadı.'));reader.readAsDataURL(file);});state.assistantImageData=data;$('#logosAssistantImagePreview').innerHTML=`<img src="${esc(data)}" alt="Asistan görsel ön izlemesi">`;}
function assistantScreenContext(){const module=state.studioModule||state.currentDynamicModule;const columns=(state.currentView==='finance'?state.financeTableColumns:state.tableColumns).filter(item=>item.visible).map(item=>item.label||item.key);return{current_view:state.currentView,current_module:module?.label||'',module_fields:(module?.fields||[]).map(item=>item.label),module_actions:(module?.actions||[]).map(item=>`${item.label} · ${item.placement}`),visible_columns:columns};}
function renderChangePreview(result,mode='platform'){state.platformPreviewToken=result.token||'';state.platformPreviewMode=mode;$('#platformChangeSummary').textContent=mode==='assistant'?`LOGOS Asistan: ${result.summary}`:result.summary;$('#platformChangeImpact').textContent=`Etkilenecek kayıt / öğe: ${number(result.impact)}`;const risk=$('#platformChangeRisk');if(result.risk){risk.hidden=false;risk.className=`risk-badge ${esc(result.risk)}`;risk.textContent=`Risk: ${String(result.risk).toLocaleUpperCase('tr-TR')}`;}else risk.hidden=true;$('#platformChangeOperations').innerHTML=(result.operations||[]).map((item,index)=>`<div class="assistant-plan-item"><strong>${index+1}. ${esc(item.summary||item.semantic?.reason||item.operation||'İşlem')}</strong><small>${esc(item.semantic?.kind||item.operation||'')} · ${esc(item.risk||'low')}</small></div>`).join('');$('#platformChangeWarnings').innerHTML=(result.warnings||[]).map(item=>`<div class="warning-line">${esc(item)}</div>`).join('');$('#platformChangePreviewDialog').showModal();}
async function previewAssistantCommand(event){event.preventDefault();const form=event.currentTarget;if(!form.reportValidity())return;try{const result=(await api('/api/assistant/preview',{method:'POST',body:{message:form.elements.command.value,image_data_url:state.assistantImageData,screen_context:assistantScreenContext()}})).data;state.platformAfterCommit=null;if(result.assistant_only||!result.token){renderAssistantReply(result);return;}$('#logosAssistantReply').hidden=true;$('#logosAssistantDialog').close();renderChangePreview(result,'assistant');}catch(error){renderAssistantReply({summary:'İstek güvenli biçimde planlanamadı; programda değişiklik yapılmadı.',warnings:[error.message],suggestions:['Hedef bölümü adıyla belirtin','yardım']});}}
function openDynamicRuleEditor(rule=null){const form=$('#dynamicRuleForm');form.reset();form.elements.id.value=rule?.id||'';form.elements.module_id.value=state.studioModule.id;form.elements.name.value=rule?.name||'';form.elements.active.checked=rule?.active??true;$('#dynamicRuleConditions').innerHTML='';$('#dynamicRuleActions').innerHTML='';(rule?.conditions?.length?rule.conditions:[{}]).forEach(addDynamicConditionRow);(rule?.actions?.length?rule.actions:[{}]).forEach(addDynamicActionRow);$('#dynamicRuleDialog').showModal();}
async function previewPlatformChange(operation,payload,afterCommit=null){try{const result=(await api('/api/platform/change/preview',{method:'POST',body:{operation,payload}})).data;state.platformAfterCommit=afterCommit;renderChangePreview(result,'platform');}catch(error){toast(error.message,true);}}
async function commitPlatformChange(){try{const endpoint=state.platformPreviewMode==='assistant'?'/api/assistant/commit':'/api/platform/change/commit';await api(endpoint,{method:'POST',body:{token:state.platformPreviewToken}});$('#platformChangePreviewDialog').close();state.platformPreviewMode='platform';await loadPlatformBootstrap();if(state.currentDynamicModule)state.currentDynamicModule=platformModule(state.currentDynamicModule.id)||null;if(state.studioModule)state.studioModule=platformModule(state.studioModule.id)||null;renderPlatformStudio();if(state.currentView==='dynamicModule'&&state.currentDynamicModule)await loadDynamicModule();const callback=state.platformAfterCommit;state.platformAfterCommit=null;if(callback)await callback();toast('Değişiklik güvenli biçimde yayınlandı.');}catch(error){toast(error.message,true);}}
async function saveDynamicModuleDefinition(event){event.preventDefault();const data=formPayload(event.currentTarget);delete data.custom_values;event.currentTarget.closest('dialog').close();await previewPlatformChange('module.save',data);}
async function saveDynamicFieldDefinition(event){event.preventDefault();const data=formPayload(event.currentTarget);delete data.custom_values;data.options=data.options.split(',').map(item=>item.trim()).filter(Boolean);event.currentTarget.closest('dialog').close();await previewPlatformChange('field.save',data);}
async function saveDynamicRuleDefinition(event){event.preventDefault();const form=event.currentTarget,data=formPayload(form);delete data.custom_values;data.conditions=$$('.platform-condition',$('#dynamicRuleConditions')).map(row=>({field:$('[data-rule-condition-field]',row).value,operator:$('[data-rule-condition-operator]',row).value,value:$('[data-rule-condition-value]',row).value})).filter(item=>item.field);data.actions=$$('.platform-action',$('#dynamicRuleActions')).map(row=>({type:$('[data-rule-action-type]',row).value,field:$('[data-rule-action-field]',row).value,value:$('[data-rule-action-value]',row).value})).filter(item=>item.field);form.closest('dialog').close();await previewPlatformChange('rule.save',data);}
async function archiveStudioModule(){if(!state.studioModule)return;await previewPlatformChange('module.archive',{id:state.studioModule.id},async()=>{state.studioModule=null;renderPlatformStudio();});}
async function restoreStudioModule(id){await previewPlatformChange('module.restore',{id});}
async function purgeStudioModule(id){const module=(state.platformBootstrap.archived_modules||[]).find(item=>item.id===id);if(!module)return;const confirmation=prompt(`${module.label} bölümü ve içindeki tüm dinamik kayıtlar kalıcı silinecek. Bu işlem arşivden geri alınamaz. Devam etmek için SIL yazın.`);if(String(confirmation||'').trim().toLocaleUpperCase('tr-TR')!=='SİL'&&String(confirmation||'').trim().toUpperCase()!=='SIL')return;await previewPlatformChange('module.delete_permanent',{id,confirmation:'SIL'},async()=>{if(state.studioModule?.id===id)state.studioModule=null;});}
