async function loadPortalAutoSyncStatus(){try{const status=(await api('/api/portal/autosync/status')).data;state.portalAutoSync=status;const textEl=$('#portalAutoSyncStatusText');if(status.enabled){textEl.className='assistant-mode success';textEl.textContent=`🟢 30 Dk Otomatik Çekim Aktif (${status.mode==='cookie'?'Otomatik Oturum Çerez Modu ⭐':'Giriş Modu'}) · Son: ${status.last_sync_at||'Henüz yapılmadı'}${status.next_sync_at?` · Sonraki: ${status.next_sync_at}`:''}`;}else{textEl.className='assistant-mode';textEl.textContent='⚪ Otomatik Çekim Pasif';}if(status.cookie_sample)$('#portalCookieString').placeholder=`Mevcut Çerez: ${status.cookie_sample}`;if(status.username)$('#portalInterUsername').value=status.username;if(status.interval_minutes)$('#portalCookieInterval').value=String(status.interval_minutes);$('#portalCookieEnabled').checked=status.enabled;}catch(e){}}
function generateBrowserAutoScript(){const host=location.origin,token=state.token||'';return `// === LOGOS TECH - Canlı Portal Verisi & Hataları Çekme Kodu ===
// okulguvenligi.com/uye/panel/kurumlar sayfasındayken F12 > Console sekmesine kopyalayıp yapıştırın:
(async function logosSync() {
  try {
    console.log('%c[LOGOS TECH] ds._data JSON + Hatalar Senkronizasyonu Başlatılıyor...', 'color:#0284c7;font-weight:bold;');
    
    function formatHatalar(hatalar) {
      if (!hatalar || !Array.isArray(hatalar) || hatalar.length === 0) return "";
      var metinler = hatalar.map(function(h) {
        if (typeof h === 'string') return h.trim();
        if (typeof h === 'object' && h !== null) {
          var txt = h.mesaj || h.baslik || h.aciklama || h.tanim || h.hata || h.metin || h.title || h.name;
          if (txt) return txt;
          return Object.keys(h).map(function(k){ return h[k]; }).filter(function(v){ return typeof v==='string'||typeof v==='number'; }).join(' - ');
        }
        return String(h);
      }).filter(function(t){ return t && t.length > 0; });
      return metinler.length > 0 ? metinler.join(" · ") : "";
    }

    var anaokuluKelimeler = ['anaokul','anasınıf','anasinif','kreş','kres','yuva','montessori','kindergarten'];
    var items = ds._filteredKeys
      .map(function(k){ return ds._data.get(k); })
      .filter(function(k){
        var ad = (k.adi||'').toLocaleLowerCase('tr');
        return !anaokuluKelimeler.some(function(w){ return ad.includes(w); });
      });

    var payload = items.map(function(item) {
      var hatalarMetni = formatHatalar(item.hatalar);
      return {
        portal_id: String(item.id || ''),
        institution_code: String(item.kurum_kodu || ''),
        name: item.adi || '',
        city: item.il || '',
        district: item.ilce || '',
        active: (item.aktif === 1 || item.aktif === true || item.aktif === '1') ? true : false,
        notes: hatalarMetni,
        health_status: hatalarMetni ? 'Kurumda Hatalar Var' : 'Kurumda sorun yok',
        sales_period: item.sd || '',
        sales_person: item.st || '',
        dealer: item.by || 'LOGOS',
        marketing_person: item.satis_temsilcisi || '',
        customer_person: item.musteri_temsilcisi || '',
        technical_person: item.teknik_servis_temsilcisi || '',
        accounting_person: item.muhasebe_temsilcisi || ''
      };
    });

    var res = await fetch('${host}/api/portal/sync/json', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'X-App-Token': '${token}' },
      body: JSON.stringify({ institutions: payload })
    });
    var data = await res.json();
    console.log('%c[LOGOS TECH] Senkronizasyon Tamamlandı! ✅', 'color:#15865d;font-weight:bold;font-size:14px;', data);
    alert('[LOGOS TECH] ✅ ' + payload.length + ' kurum aktarıldı!\nYeni: ' + (data.new||0) + ' · Güncellendi: ' + (data.updated||0));
  } catch(e) { console.error('[LOGOS TECH] Hata:', e); alert('[LOGOS TECH] Hata: ' + e.message); }
})();`;}

async function startSmsLogin(){const username=$('#portalInterUsername').value.trim(),password=$('#portalInterPassword').value;if(!username||!password){toast('Lütfen kullanıcı adı ve şifre girin.',true);return;}try{$('#btnStartSmsLogin').disabled=true;$('#btnStartSmsLogin').textContent='⏳ Giriş yapılıyor ve SMS kodu gönderiliyor...';const res=(await api('/api/portal/login/start',{method:'POST',body:{username,password}})).data;$('#portalSmsSessionId').value=res.session_id;$('#portalSmsMessage').textContent=res.message||'📲 SMS Doğrulama Kodu Telefonunuza Gönderildi!';$('#portalSmsCodeStep').hidden=false;$('#portalSmsCodeInput').focus();toast('SMS kodu telefonunuza gönderildi!');}catch(error){toast(error.message,true);}finally{$('#btnStartSmsLogin').disabled=false;$('#btnStartSmsLogin').textContent='📱 1. Adım: Giriş Yap ve SMS Kodu Gönder';}}
async function verifySmsLogin(){const session_id=$('#portalSmsSessionId').value,sms_code=$('#portalSmsCodeInput').value.trim(),interval_minutes=Number($('#portalInterInterval').value);if(!sms_code){toast('Lütfen telefonunuza gelen SMS kodunu girin.',true);return;}try{$('#btnVerifySmsCode').disabled=true;$('#btnVerifySmsCode').textContent='⏳ SMS doğrulanıyor ve oturum çerezi kaydediliyor...';await api('/api/portal/login/verify-sms',{method:'POST',body:{session_id,sms_code,interval_minutes}});$('#portalSyncDialog').close();toast(`✅ SMS doğrulandı! ${interval_minutes} dakikada bir otomatik veri çekme görevi başlatıldı.`);await Promise.all([loadFilters(),loadAllInstitutions(),refreshInstitutions()]);}catch(error){toast(error.message,true);}finally{$('#btnVerifySmsCode').disabled=false;$('#btnVerifySmsCode').textContent='✅ 2. Adım: SMS Kodunu Onayla & 30 Dk Otomatik Görevi Başlat';}}
