async function handlePortalSync(event){event.preventDefault();const mode=$('#portalSyncMode').value;try{let result;if(mode==='text'){const content=$('#portalSyncContent').value.trim();if(!content)throw new Error('Lütfen kopyalanan metni veya HTML kaynağını yapıştırın.');result=(await api('/api/portal/sync/text',{method:'POST',body:{content}})).data;toast(`${number(result.new)} yeni kurum eklendi, ${number(result.updated)} kurum güncellendi! Toplam ${number(result.total)} kurum senkronize edildi.`);}else if(mode==='cookie'){const cookie_string=$('#portalCookieString').value.trim(),interval_minutes=Number($('#portalCookieInterval').value),enabled=$('#portalCookieEnabled').checked;await api('/api/portal/autosync/settings',{method:'POST',body:{enabled,mode:'cookie',cookie_string,interval_minutes,trigger_now:true}});toast(enabled?`SMS koduna gerek kalmadan ${interval_minutes} dakikada bir otomatik veri çekme görevi başlatıldı!`:'Otomatik veri çekme görevi durduruldu.');}$('#portalSyncDialog').close();await Promise.all([loadFilters(),loadAllInstitutions(),refreshInstitutions()]);}catch(error){toast(error.message,true);}}
let currentFaultyInstitutions=[];function generateGeminiReasoning(mode,items){if(!items||items.length===0){return '✅ Sistemde şu an aktif hiçbir hata tespit edilmedi. Tüm turnike ve panel bağlantıları sorunsuz çalışmaktadır.';}const latest=items[0],reasonsStr=latest.reasons||'Genel Hata Bilgisi';if(mode==='latest'){let r=`<b>⚡ En Son Sisteme Düşen Hatalı Kurum Analizi:</b><br>• <b>Kurum:</b> ${esc(latest.name)} (${esc(latest.city)} / ${esc(latest.district)})<br>• <b>Tespit Edilen Kök Neden:</b> <span style="color:#fca5a5;">${esc(reasonsStr)}</span><br>• <b>Gemini Tavsiyesi:</b> `;if(reasonsStr.includes('İPTAL')||reasonsStr.includes('PASİF')){r+=`Sözleşme iptal sürecinde olduğu için turnike ve kartlı geçiş erişimleri durdurulmalı. Müşteri temsilcisi ile görüşülüp iptal kaydı teyit edilmelidir.`;}else if(reasonsStr.includes('Ödeme')||reasonsStr.includes('BORÇ')){r+=`Finansal borç/gecikme uyarısı mevcut. Otomatik kesinti öncesinde kuruma muhasebe bildirim mesajı iletilmelidir.`;}else if(reasonsStr.includes('Kamera')){r+=`Kamera RTSP/IP veri akışı kesilmiş. Yerel ağ modem ve anahtarlayıcı (switch) cihazları kontrol edilmelidir.`;}else{r+=`Sistem sağlık puanı kritik seviyeye düştüğü için saha teknik ekibine kontrol görevi atanmalıdır.`;}return r;}else if(mode==='iptal'){return `<b>🚫 Sözleşme İptalleri Karar Analizi:</b><br>Toplam ${items.length} kurumda sözleşme iptal veya pasif durumu mevcut. Bu kurumların veritabanı lisans kullanımı sonlandırılmalı ve donanım söküm planı oluşturulmalıdır.`;}else if(mode==='odeme'){return `<b>💳 Ödeme & Finans Aksiyon Analizi:</b><br>Toplam ${items.length} kurumda ödeme alacağı gecikmiştir. Otomatik hatırlatma SMS/E-posta servisi tetiklenebilir.`;}else if(mode==='camera'){return `<b>📹 Kamera & IP Akış Analizi:</b><br>Toplam ${items.length} kurumda kamera arızası ve görüntü kaybı tespit edilmiştir. Teknik servis ekibine otomatik iş emri iletilmesi önerilir.`;}else{return `<b>🧠 Genel Gemini AI Sistem Analizi:</b><br>Sistem genelinde ${items.length} hatalı/iptal kayıt izleniyor. En kritik son durum <b>${esc(latest.name)}</b> kurumundadır.`;}}
function renderFaultyListByMode(){const mode=$('#aiFaultyFilterMode').value;let items=[...currentFaultyInstitutions];if(mode==='latest'){items=items.slice(0,1);}else if(mode==='last_5'){items=items.slice(0,5);}else if(mode==='last_10'){items=items.slice(0,10);}else if(mode==='iptal'){items=items.filter(x=>(x.reasons||'').includes('İPTAL')||(x.reasons||'').includes('PASİF'));}else if(mode==='odeme'){items=items.filter(x=>(x.reasons||'').includes('Ödeme')||(x.reasons||'').includes('BORÇ'));}else if(mode==='camera'){items=items.filter(x=>(x.reasons||'').includes('Kamera'));}$('#geminiReasoningText').innerHTML=generateGeminiReasoning(mode,items);if(items.length===0){$('#aiFaultyList').innerHTML='<div style="text-align:center;color:#10b981;padding:20px;font-weight:600;">✅ Seçilen filtreye uygun hatalı kurum bulunamadı.</div>';}else{let html='';items.forEach(item=>{html+=`<div style="background:rgba(15,23,42,0.8);border:1px solid #1e293b;border-left:3px solid #ef4444;border-radius:6px;padding:10px 12px;margin-bottom:8px;display:flex;justify-content:space-between;align-items:center;"><div style="flex:1;padding-right:12px;"><strong style="color:#f8fafc;font-size:13px;display:block;margin-bottom:2px;">${esc(item.name)}</strong><span style="color:#94a3b8;font-size:11px;display:block;">📍 ${esc(item.city)} / ${esc(item.district)} · <span style="color:#fca5a5;">⚠️ ${esc(item.reasons)}</span></span></div><div style="text-align:right;min-width:85px;"><span class="badge danger" style="background:#991b1b;color:#fecdd3;font-size:10px;display:inline-block;margin-bottom:2px;">🕒 ${esc(item.time_display)}</span><span style="display:block;font-size:10px;color:#64748b;">${esc((item.updated_at||'').split(' ')[0]||(item.updated_at||'').split('T')[0]||'')}</span></div></div>`;});$('#aiFaultyList').innerHTML=html;}}
// Tab switching function (exposed to window + direct listeners)
function switchAiTab(tab){
  const tabs=['chat','faults'];
  tabs.forEach(t=>{
    const btn=$('#aiTab_'+t);
    const content=$('#aiTabContent_'+t);
    if(!btn||!content)return;
    const active=t===tab;
    btn.style.borderBottomColor=active?'#0284c7':'transparent';
    btn.style.color=active?'#38bdf8':'#64748b';
    btn.style.fontWeight=active?'700':'600';
    content.style.display=active?'flex':'none';
  });
  if(tab==='faults') renderFaultyListByMode();
}
window.switchAiTab=switchAiTab;

async function openAiRobotAssistant(){
  $('#logosAiRobotDialog').showModal();
  switchAiTab('chat'); // always start on chat tab
  $('#aiFaultyList').innerHTML='<div style="text-align:center;color:#64748b;padding:20px;">🤖 Asistan verileri tarıyor…</div>';
  $('#aiLastSyncTime').textContent='Yükleniyor…';
  $('#aiAutoSyncBadge').textContent='';
  try{
    const res=(await api('/api/assistant/robot-status')).data;
    const autosync=res.autosync||{};
    currentFaultyInstitutions=res.faulty_institutions||[];
    
    // Format timestamp robustly
    const lastSync=autosync.last_sync_at;
    if(lastSync && lastSync !== '—'){
      // Replace space with T to create valid ISO string for Date parsing
      const isoStr=String(lastSync).replace(' ','T');
      const d=new Date(isoStr);
      if(!isNaN(d.getTime())){
        const now=new Date();
        const isToday=d.toDateString()===now.toDateString();
        const timeStr=d.toLocaleTimeString('tr-TR',{hour:'2-digit',minute:'2-digit',second:'2-digit'});
        const dateStr=isToday?`Bugün ${timeStr}`:d.toLocaleDateString('tr-TR',{day:'2-digit',month:'2-digit'})+' '+timeStr;
        $('#aiLastSyncTime').textContent=dateStr;
      } else {
        $('#aiLastSyncTime').textContent=lastSync;
      }
    } else {
      $('#aiLastSyncTime').textContent='Canlı Oturum Açılmadı';
    }

    // Auto-sync badge
    if(autosync.enabled){
      $('#aiAutoSyncBadge').textContent=`🟢 ${autosync.interval_minutes||30} dk otomatik aktif`;
      $('#aiAutoSyncBadge').style.color='#34d399';
    } else {
      $('#aiAutoSyncBadge').textContent='⚪ Otomatik pasif';
      $('#aiAutoSyncBadge').style.color='#94a3b8';
    }

    // Fault count badge on tab button
    const faultCount=currentFaultyInstitutions.length;
    const badge=$('#aiFaultCountBadge');
    if(badge) badge.textContent=faultCount>0?faultCount:'';
    renderFaultyListByMode();
  }catch(e){toast(e.message,true);}
}

// Bind tab click event listeners
