// =================== AI CHAT ENGINE ===================
// State for conversational login flow
let _aiChatLoginState={step:'idle',username:'',password:'',sessionId:''};

function addAiChatMsg(text,isUser=false){
  const feed=$('#aiChatFeed');if(!feed)return;
  const div=document.createElement('div');
  div.style.cssText=isUser
    ?'align-self:flex-end;background:linear-gradient(135deg,#0284c7,#0f766e);color:#fff;border-radius:8px;padding:8px 12px;font-size:12px;max-width:80%;'
    :'align-self:flex-start;background:#1e293b;color:#f8fafc;border-radius:8px;padding:8px 12px;font-size:12px;max-width:88%;border-left:3px solid #0284c7;';
  div.innerHTML=isUser
    ?`<strong style="color:#bae6fd;display:block;font-size:11px;">👤 Siz</strong>${esc(text)}`
    :`<strong style="color:#38bdf8;display:block;font-size:11px;">🤖 LOGOS TECH AI</strong>${text}`;
  feed.appendChild(div);
  feed.scrollTop=feed.scrollHeight;
}

async function handleAiChatInput(rawText){
  const text=(rawText||'').trim();if(!text)return;
  addAiChatMsg(text,true);
  const lower=text.toLowerCase();

  // --- 1. "veri çek" / "sync" ---
  if(/veri.?çek|senkronize|sync|refresh/i.test(lower)){
    addAiChatMsg('🔄 Portal verilerini çekmeye çalışıyorum...');
    try{
      const statusRes=(await api('/api/portal/autosync/status')).data;
      if(!statusRes.has_cookie&&!statusRes.has_password){
        addAiChatMsg('🔐 Henüz oturum açılmamış. Lütfen <b>kullanıcı adınızı</b> yazın:');
        _aiChatLoginState={step:'ask_username',username:'',password:'',sessionId:''};
      } else {
        const r=(await api('/api/portal/autosync/trigger',{method:'POST'})).data;
        if(r.ok){addAiChatMsg('✅ Portal verileri başarıyla güncellendi! Tablonuzu yenileyebilirsiniz.');await Promise.all([loadFilters(),loadAllInstitutions(),refreshInstitutions()]);await openAiRobotAssistant();}
        else{addAiChatMsg(`⚠️ Veri çekilemedi: <b>${esc(r.error||'Bilinmeyen hata')}</b>. Lütfen tekrar giriş yapın.<br><b>Kullanıcı adınızı</b> yazın:`);_aiChatLoginState={step:'ask_username',username:'',password:'',sessionId:''};}
      }
    }catch(e){addAiChatMsg(`❌ Hata: ${esc(e.message)}`);}
    return;
  }

  // --- 2. Conversational login flow ---
  if(_aiChatLoginState.step==='ask_username'||/kullanıcı.?adı|username|e.?posta|email|giriş.?yap|login/i.test(lower)){
    if(_aiChatLoginState.step==='ask_username'){
      _aiChatLoginState.username=text;
      _aiChatLoginState.step='ask_password';
      addAiChatMsg('🔑 Teşekkürler! Şimdi <b>şifrenizi</b> yazın (ekranda görünmez, güvendesiniz):');
      return;
    }
    if(_aiChatLoginState.step==='idle'||_aiChatLoginState.step===''){
      addAiChatMsg('📧 okulguvenligi.com <b>kullanıcı adınızı</b> (e-posta) yazın:');
      _aiChatLoginState={step:'ask_username',username:'',password:'',sessionId:''};
      return;
    }
  }

  if(_aiChatLoginState.step==='ask_password'){
    _aiChatLoginState.password=text;
    _aiChatLoginState.step='sending_sms';
    addAiChatMsg('⏳ Giriş yapılıyor, telefonunuza SMS kodu gönderiliyor...');
    try{
      const res=(await api('/api/portal/login/start',{method:'POST',body:{username:_aiChatLoginState.username,password:_aiChatLoginState.password}})).data;
      _aiChatLoginState.sessionId=res.session_id;
      _aiChatLoginState.step='ask_sms';
      addAiChatMsg(`📲 <b>SMS kodu gönderildi!</b> ${esc(res.message||'')}<br>Telefonunuza gelen <b>6 haneli kodu</b> yazın:`);
    }catch(e){addAiChatMsg(`❌ Giriş başarısız: ${esc(e.message)}<br>Lütfen tekrar <b>kullanıcı adınızı</b> yazın.`);_aiChatLoginState={step:'ask_username',username:'',password:'',sessionId:''};}
    return;
  }

  // --- 3. SMS code entry (conversational or direct "sms kodu 485921") ---
  const smsMatch=text.match(/(?:sms|kod)[:\s]*(\d{4,8})/i)||text.match(/^(\d{4,8})$/);
  if(smsMatch||_aiChatLoginState.step==='ask_sms'){
    const code=smsMatch?smsMatch[1]:text;
    if(!_aiChatLoginState.sessionId){addAiChatMsg('⚠️ Önce giriş başlatmalısınız. <b>Kullanıcı adınızı</b> yazın:');_aiChatLoginState={step:'ask_username',username:'',password:'',sessionId:''};return;}
    addAiChatMsg(`⏳ SMS kodu <b>${esc(code)}</b> doğrulanıyor...`);
    try{
      await api('/api/portal/login/verify-sms',{method:'POST',body:{session_id:_aiChatLoginState.sessionId,sms_code:code,interval_minutes:30}});
      _aiChatLoginState={step:'idle',username:'',password:'',sessionId:''};
      addAiChatMsg('✅ <b>Giriş ve Oturum Başarılı!</b> Canlı portal verileri çekildi ve veritabanınız güncellendi. 30 dakikada bir otomatik çekim aktif.');
      await Promise.all([loadFilters(),loadAllInstitutions(),refreshInstitutions()]);
      await openAiRobotAssistant();
    }catch(e){addAiChatMsg(`❌ SMS doğrulama hatası: ${esc(e.message)}<br>Kodu tekrar girin veya <b>"veri çek"</b> yazarak yeniden başlayın.`);_aiChatLoginState.step='ask_sms';}
    return;
  }

  // --- 4. "analiz" / fault analysis chip ---
  if(/analiz|hata|sorun|fault|kök.?neden|neden/i.test(lower)){
    const mode=$('#aiFaultyFilterMode')?.value||'latest';
    renderFaultyListByMode();
    const txt=$('#geminiReasoningText')?.innerHTML||'';
    addAiChatMsg('🧠 <b>Gemini AI Kök Neden Analizi:</b><br>'+txt.replace(/<[^>]+>/g,' ').trim());
    return;
  }

  // --- 5. Free-form → send to Gemini via /api/assistant/preview ---
  addAiChatMsg('🧠 Gemini ile analiz ediyorum...');
  try{
    const res=(await api('/api/platform/assistant/preview',{method:'POST',body:{command:text,screen_context:{current_view:'ai_chat',current_module:'LOGOS TECH AI Asistan'}}})).data;
    const reply=res.assistant_text||res.summary||'Gemini yanıt üretemedi.';
    addAiChatMsg(esc(reply).replace(/\n/g,'<br>'));
  }catch(e){addAiChatMsg(`⚠️ Gemini bağlantısı kurulamadı: ${esc(e.message)}<br><small>Gemini API Key ayarlı mı? 🔑 butonuna tıklayın.</small>`);}
}

