function moveListRow(event){const button=event.target.closest('button');if(!button)return;const row=button.closest('.column-row');if(!row)return;if(button.textContent==='↑'&&row.previousElementSibling)row.parentNode.insertBefore(row,row.previousElementSibling);else if(button.textContent==='↓'&&row.nextElementSibling)row.parentNode.insertBefore(row.nextElementSibling,row);else if(button.classList.contains('pin-column'))button.classList.toggle('active');else if(button.classList.contains('remove-column')){$('input[type="checkbox"]',row).checked=false;button.closest('.column-actions').querySelector('.pin-column')?.classList.remove('active');}else if(button.classList.contains('remove-filter-setting'))$('input[type="checkbox"]',row).checked=false;}
function moveConfigRow(event){const button=event.target.closest('[data-config-move]');if(!button)return;const row=button.closest('[draggable="true"]');if(!row)return;if(button.dataset.configMove==='up'&&row.previousElementSibling)row.parentNode.insertBefore(row,row.previousElementSibling);if(button.dataset.configMove==='down'&&row.nextElementSibling)row.parentNode.insertBefore(row.nextElementSibling,row);}
async function initialize(){try{const session=await api('/api/session');state.token=session.token;state.assistantStatus=session.assistant||state.assistantStatus;$('#versionLabel').textContent=`Sürüm ${session.version}`;const[custom,financeFields,lookups,institutionForm,institutionFilters,financeFilters,tableColumns,financeColumns,summaryCards,savedViews,navigation,theme,platform]=await Promise.all([api('/api/custom-fields'),api('/api/finance/fields'),api('/api/lookups'),api('/api/settings/institution-form'),api('/api/settings/filters'),api('/api/settings/finance-filters'),api('/api/settings/table-columns'),api('/api/settings/finance-table-columns'),api('/api/settings/finance-summary-cards'),api('/api/settings/finance-saved-views'),api('/api/settings/navigation'),api('/api/settings/theme'),api('/api/platform/bootstrap')]);state.customFields=custom.data;state.financeFields=financeFields.data;state.lookupCategories=lookups.data;state.institutionFormFields=institutionForm.data;state.institutionFilterConfig=institutionFilters.data;state.financeFilterConfig=financeFilters.data;state.tableColumns=mergeColumns(tableColumns.data);state.financeTableColumns=mergeFinanceColumns(financeColumns.data);state.financeSummaryCards=summaryCards.data;state.financeSavedViews=savedViews.data;state.navigationPreferences=navigation.data;state.themePreferences=theme.data;state.platformBootstrap=platform.data;state.dynamicModules=platform.data.modules||[];renderDynamicNavigation();renderPlatformStudio();const defaultView=state.financeSavedViews.find(item=>item.is_default);if(defaultView){state.activeFinanceView=defaultView;state.financeSelections=structuredClone(defaultView.selections||{});state.financeRanges=structuredClone(defaultView.ranges||{});state.financeTableColumns=mergeFinanceColumns(defaultView.columns||[]);$('#financeSearch').value=defaultView.search||'';}applyNavigation();applyTheme();bindEvents();await Promise.all([loadFilters(),loadAllInstitutions(),refreshInstitutions()]);updateActiveFinanceViewBanner();}catch(error){toast(error.message,true);}}
initialize();
